window.CHAT = {"teknik-gelistirim": {"language": "en", "items": [{"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "How are multitenant Container Database (CDB$ROOT) and Pluggable Database (PDB) structures used to isolate IFS environments?", "a": "The root container database (CDB\\(ROOT) manages background processes, shared system metadata, and global memory allocations. Dedicated Pluggable Databases, including PDB\\)SEED and user PDBs, isolate separate IFS application instances like DEV, TEST, and PROD on the same server hardware. This multitenant structure provides database-level isolation for data dictionaries and application schemas. The sources apply these multitenant architecture principles to IFS Applications (IFS Cloud and IFS Applications 10/9) without restricting them to a specific database version.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "How do Buffer Cache and Shared Pool memory components within the SGA support IFS mid-tier session activity?", "a": "Within the System Global Area (SGA), the Shared Pool stores parsed SQL and PL/SQL code, execution plans, and data dictionary information for reuse by IFS mid-tier sessions. The Buffer Cache caches data blocks read from disk to optimize query response times and reduce physical I/O. Dynamic allocation under sga_target balances these two components based on operational workload demands. The sources describe these SGA memory functions for IFS Applications (IFS Cloud and IFS Applications 10/9) without stating a specific database version restriction.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "How does setting an insufficient value for the processes parameter affect IFS mid-tier connections?", "a": "The processes static initialization parameter specifies the maximum number of operating system user processes that can simultaneously connect to the Oracle database instance. Each dedicated mid-tier connection pool, background process (such as PMON, DBWn, and LGWR), and DBA session consumes a process slot. Configuring this parameter too low causes incoming connections to be rejected with the ORA-00020: maximum number of processes exceeded error, preventing mid-tier application servers from establishing new sessions. The sources do not place a version restriction on this parameter definition.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "How is the curriculum for the IFS Enterprise Oracle DBA Training Program structured during program orientation?", "a": "During program orientation, the training curriculum is structured to align learner objectives with core architectural guidelines and technical tracks. The program covers foundational modules including multitenant isolation, RAC clustering, ASM storage management, Data Guard disaster recovery, and AWR/ASH performance diagnostics. It establishes a progressive learning roadmap for database administrators managing mission-critical enterprise workloads. The sources outline this training structure specifically for the IFS Enterprise Oracle Architecture & DBA Training Program.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What details do the sources provide regarding Oracle 19c database storage tiering and server requirements for IFS Cloud 25R1 and 26R2?", "a": "The selected sources do not contain specific technical details or sizing metrics regarding Oracle 19c storage tiering or server hardware requirements for IFS Cloud 25R1 and IFS Cloud 26R2. They only note generally that IFS Applications (IFS Cloud and IFS Applications 10/9) rely on Oracle Database backends for core ERP, EAM, and FSM workloads. The absence of specific storage tier and server sizing details for these releases is explicitly noted as not covered in the sources.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What foundational database pillars govern the Oracle infrastructure for mission-critical IFS enterprise applications?", "a": "The Oracle infrastructure guidelines for IFS enterprise applications are structured around five core architectural pillars. These pillars encompass multitenant database configuration, high availability frameworks, robust disaster recovery protocols, continuous performance tuning, and centralized system monitoring. Together, they provide database administrators with a blueprint to maintain a secure, scalable, and resilient operational environment. The sources present these guidelines for IFS Applications and IFS Cloud enterprise workloads without restricting them to a single database version.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What happens when the sga_target parameter is set to a non-zero value in an IFS Applications environment?", "a": "Setting sga_target to a non-zero value enables Automatic Shared Memory Management (ASMM) in the Oracle database. Under ASMM, Oracle dynamically balances memory allocation among the Buffer Cache, Shared Pool, Large Pool, and Java Pool. This dynamic tuning prevents hard parsing and disk I/O bottlenecks during heavy OLTP operations in IFS Applications (IFS Cloud and IFS Applications 10/9). The sources do not specify a database version restriction for these ASMM parameter definitions.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What is the difference between Release Update (RU) and Release Update Revision (RUR) in the Oracle maintenance lifecycle for IFS environments?", "a": "A Release Update (RU) is a quarterly cumulative patch containing security vulnerability fixes, high-value bug fixes, and stability improvements that increments the secondary version number. A Release Update Revision (RUR) extends the lifespan of a specific RU by providing security and regression fixes without introducing new functional bug fixes. RU patches are applied in non-production environments (DEV and TEST) during major update cycles, while RUR patches are preferred in production (PROD) to lock execution behavior. The sources present these patch lifecycle definitions for Oracle Database 19c and IFS Applications 10/9.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What is the purpose of the pga_aggregate_target parameter and how does it prevent performance degradation?", "a": "The pga_aggregate_target parameter establishes a global target for the total Program Global Area (PGA) memory allocated across all database sessions. It dynamically controls memory allocated to work areas for ORDER BY sorts, hash joins, and bitmap merges to keep them within limits. Proper configuration prevents excessive spilling of work area data to temporary tablespace during heavy batch reporting in IFS Applications (IFS Cloud and IFS Applications 10/9). The sources do not specify a version constraint for this PGA parameter setting.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 1, "title": "Program Orientation and IFS Cloud Oracle Architecture", "q": "What role does the open_cursors parameter play in managing Private SQL Area resources for Java/JDBC connection pools?", "a": "The dynamic open_cursors parameter specifies the maximum number of open cursors a single session can hold simultaneously in its Private SQL Area. Mid-tier frameworks, such as Java/JDBC connection pools in IFS environments, cache statement handles to increase execution speed. Setting this parameter sufficiently high prevents cursor leaks and Shared Pool memory exhaustion, avoiding the ORA-01000: maximum open cursors exceeded error in IFS Applications. The sources do not state a specific version restriction for this parameter.", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-060-development-025-operational-reporting-2026-11-08-09_42_53.pdf", "url": ""}, {"title": "IFS Oracle DBA Training Progress", "url": ""}, {"title": "IFS Oracle DBA Eğitim Güncellemesi", "url": ""}, {"title": "Training Progress and Chapter 6 Start", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "How do PDB Resource Manager profiles prevent nonproduction workloads from impacting core Production performance?", "a": "PDB Resource Manager profiles allocate dedicated CPU shares, parallel execution queues, and session limits per PDB [1]. These controls prevent heavy testing scripts or batch jobs in one PDB from consuming excessive shared system resources [1]. Protecting core production workloads from resource starvation maintains consistent operational throughput [1]. The sources do not limit PDB Resource Manager profiles to a specific database version [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "How do midtier connection pools interact with PDB services to preserve logical isolation across IFS environments?", "a": "Midtier connection pools interact exclusively with their assigned PDB service name [1]. This transactional context switching prevents sessions in nonproduction environments like Development or Testing from accessing or modifying Production schema objects [1]. Consequently, different application stages can run safely on shared physical infrastructure [1]. The sources do not specify a version constraint for this connection pool isolation mechanism [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "How is dictionary isolation maintained between individual Pluggable Databases (PDBs) and the CDB$ROOT container?", "a": "While CDB$ROOT manages common system metadata, each PDB maintains its own private data dictionary for user created tables, indexes, and application schemas [1]. Each PDB functions as an independent database to connected midtier applications [1]. This private data dictionary design prevents metadata overlap and cross environment interference [1]. The sources do not place a database version restriction on PDB data dictionary isolation [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "What core components and system resources are managed by the CDB$ROOT container in an Oracle Multitenant database?", "a": "The root container database (CDB\\(ROOT) manages background processes, shared system metadata, global memory allocations, and common database user accounts [1]. It also stores global initialization parameters shared across the multitenant structure [1]. This architecture enables different IFS application stages to share underlying database infrastructure efficiently [1]. The sources do not specify a version constraint for these CDB\\)ROOT architectural definitions [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "What data and Application schemas are stored inside User PDBs within an IFS Applications environment?", "a": "User PDBs contain application specific metadata, tablespace structures, and user data schemas required for IFS Applications workloads [1]. They are deployed as dedicated pluggable databases to completely isolate individual operational stages such as Production, Testing, or Development [1]. This isolation ensures that application schemas remain segregated at the database level [1]. The sources do not restrict User PDB operations to a single database version [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "What independent lifecycle operations can administrators perform on a PDB without affecting sibling PDBs in the same CDB?", "a": "Database administrators can unplug, clone, or drop an individual PDB without disrupting active operations in sibling PDBs running on the same CDB [1]. These independent lifecycle operations allow maintenance and upgrades on specific IFS environments without causing global system downtime [1]. This flexibility significantly reduces administrative overhead in multitenant management [1]. The sources do not restrict these PDB lifecycle operations to a specific database version [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "What is the purpose and operational role of the PDB$SEED structure when creating new pluggable databases?", "a": "The PDB\\(SEED structure serves as a system provided template Pluggable Database (PDB) used to quickly provision new pluggable databases [1]. It allows administrators to clone clean, standardized PDB instances for new IFS environments without manual setup [1]. This template mechanism accelerates environment deployment across application lifecycles [1]. The sources do not state a specific database version restriction for the PDB\\)SEED template function [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "Which SQL queries and built in functions are executed to verify session container context and active session distribution across PDBs?", "a": "To confirm the current session container context and ID, administrators query sys_context('USERENV', 'CON_NAME') and sys_context('USERENV', 'CON_ID') from the DUAL table [1]. Active session distribution across pluggable databases is audited by querying the v$session view grouped by con_id, username, and status [1]. These verification steps ensure sessions execute within their intended PDB container context [1]. The sources do not restrict these session verification queries to a specific database version [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "Which SQL statements are used by a database administrator to open a target IFS PDB and switch container context from CDB$ROOT?", "a": "To open a target pluggable database from CDB\\(ROOT, the administrator executes ALTER PLUGGABLE DATABASE ifsprod OPEN [1]. The session container context is then changed using the ALTER SESSION SET CONTAINER = ifsprod statement [1]. Current container statuses across the CDB are verified by querying the v\\)pdbs view [1]. The sources do not specify a version constraint for these multitenant SQL administration commands [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Multitenant Database Administration: CDB and PDB", "q": "Which initialization parameters are used to configure memory limits at the PDB level to control resource consumption?", "a": "PDB level memory limits are established by configuring the sga_min_size, sga_target, and pga_aggregate_limit parameters within individual pluggable databases [1]. These memory quotas prevent unconstrained queries in a single container from consuming shared host memory [1]. Setting these limits protects primary transaction processing workloads from memory contention caused by sibling PDBs [1]. The sources do not specify a database version restriction for these PDB memory control parameters [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "How is the first stage of the two stage patch application pipeline executed during database maintenance?", "a": "The first stage of the patch application pipeline involves running the opatch apply command while database services are completely shut down [1]. This command directly updates and replaces executable binaries, libraries, and header files inside the $ORACLE_HOME directory [1]. Database services remain offline until the binary patching process finishes cleanly [1]. The sources present this binary patching procedure without placing a version restriction on the command usage [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "What core functions does the AutoUpgrade utility perform during Oracle Database 19c upgrades according to official documentation?", "a": "The AutoUpgrade utility automates the end to end database upgrade process, running preupgrade checks, executing upgrade steps, and handling postupgrade tasks [1]. It provides a streamlined command line pipeline that reduces manual errors during major database version migrations [1]. The official Oracle documentation documents the AutoUpgrade utility specifically within the Oracle Database 19c Database Upgrade Guide [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "What is a Release Update (RU) in the Oracle database patch maintenance strategy and how does it impact the version number?", "a": "A Release Update (RU) is a quarterly, cumulative patch containing security vulnerability fixes, proactive high-value bug fixes, and critical stability enhancements [1]. Applying an RU moves the database to a new minor release version, incrementing the minor version digit such as from 19.11 to 19.12 [1]. In IFS Applications multitenant environments, RUs are recommended for nonproduction environments like DEV and TEST during major update cycles to validate performance changes and execution plans [1]. The sources describe this RU patch lifecycle for Oracle Database 19c and IFS Applications 10/9 environments [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "What is the primary purpose of a Release Update Revision (RUR) and how does it differ from a Release Update (RU)?", "a": "A Release Update Revision (RUR) extends the lifespan of a specific RU by delivering strictly critical security fixes and regression fixes without incorporating new functional bug fixes [1]. Applying an RUR increments the revision digit, such as moving from version 19.11.0 to 19.11.1, with up to two revisions released per RU [1]. It is primarily used in production (PROD) environments where locking core execution behavior between major application upgrades is required while maintaining security compliance [1]. The sources present this RUR patching strategy for Oracle Database 19c and IFS Applications 10/9 [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "What prerequisite verification checks must database administrators perform using the OPatch utility before installing a patch?", "a": "Before executing patch installation commands on an Oracle Database home, the OPatch utility must be updated to the minimum version specified in the Oracle Patch Readme [1]. DBAs must perform conflict detection checks against $ORACLE_HOME to prevent partial patch applications and verify system prerequisites before shutting down database services [1]. Performing these verification checks avoids software corruption and minimizes unexpected service disruptions [1]. The sources describe these OPatch verification steps without stating a specific database version restriction [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "What technical details do the selected sources provide regarding automated AutoUpgrade REST API configurations for IFS Cloud 26R2?", "a": "The selected sources do not contain specific technical deployment steps or code samples for configuring AutoUpgrade REST APIs within IFS Cloud 26R2 environments [1]. The Oracle Database 19c Database Upgrade Guide lists AutoUpgrade REST APIs as a documentation appendix, but does not detail their integration into IFS Cloud release pipelines [1]. The absence of specific IFS Cloud 26R2 AutoUpgrade REST API implementation details is explicitly noted as not covered in the selected sources [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "When is the datapatch automation utility executed in the two stage patching pipeline and what database layers does it update?", "a": "The datapatch utility is executed during the second stage of the pipeline after binary patching is complete and database services are reopened [1]. Datapatch automatically updates SQL metadata, data dictionary objects, and PL/SQL packages inside CDB$ROOT and all Pluggable Databases (PDBs) across the multitenant container structure [1]. This step ensures SQL level patch automation is fully applied across all database containers [1]. The sources describe datapatch automation for Oracle multitenant databases without specifying a database version limit [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "Which alternative utilities and tools are documented in the Oracle Database 19c upgrade guide for manual upgrades and data migration?", "a": "For manual upgrade workflows, the upgrade guide documents the Parallel Upgrade Utility to run upgrade scripts in parallel [1]. For data migration across databases, Oracle Data Pump is provided to export and import database objects and data sets [1]. The documentation presents these tools as alternative or complementary migration paths in the Oracle Database 19c Database Upgrade Guide [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "Which data dictionary views are queried by database administrators to verify applied SQL patch history and RU or RUR revision levels?", "a": "Database administrators query the registry\\(history and dba_registry_sqlpatch data dictionary views to audit applied patches [1]. These SQL queries allow DBAs to verify the current RU or RUR revision level and confirm patch application status across CDB\\)ROOT and individual pluggable databases [1]. Inspecting these views ensures that postpatch SQL automation completed successfully [1]. The sources outline the use of these dictionary views for database patch verification without restricting them to a specific version [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 3, "title": "Release Lifecycle and Patching: RU, RUR and Upgrades", "q": "Which official Oracle graphical user interface tool is available for step by step interactive database upgrades?", "a": "The Database Upgrade Assistant (DBUA) provides an interactive graphical user interface to guide database administrators step by step through the database upgrade workflow [1]. DBUA automates prerequisite checks, database configuration updates, and postupgrade verification through a visual wizard [1]. The official documentation presents DBUA as a supported upgrade option in the Oracle Database 19c Database Upgrade Guide [1].", "sources": [{"title": "Oracle for SAP Cloud and Infrastructure Update", "url": "https://www.oracle.com/a/ocom/docs/oracle-sap-cloud-infrastructure-update.pdf"}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "How do ASM External, Normal, and High Redundancy models protect database files across Failure Groups?", "a": "External Redundancy provides no mirroring within ASM and delegates data protection entirely to underlying hardware RAID controllers or SAN hardware [1]. Normal Redundancy implements 2-way mirroring requiring at least two Failure Groups, while High Redundancy implements 3-way mirroring across at least three Failure Groups [1]. High Redundancy is standard for mission-critical IFS setups requiring maximum fault tolerance [1]. The sources detail these ASM redundancy models for IFS Applications (IFS Cloud, IFS Applications 10/9) without a specific database version limit [1].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "How does ASM coarse grained striping operate and which database file types use this striping method?", "a": "ASM Coarse-Grained Striping allocates data across member disks using full Allocation Units typically sized between 1 MB and 4 MB or larger [1]. It is designed for large sequential I/O operations where reading or writing contiguous data chunks maximizes throughput [1]. Target file types for coarse-grained striping include database data files, index tablespaces, temporary files, and RMAN backup sets [1]. The sources describe Coarse-Grained Striping for IFS Applications environments without restricting it to a specific database version [1].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "How does ASM fine grained striping subdivide Allocation Units and what database file types benefit from it?", "a": "ASM Fine-Grained Striping subdivides Allocation Units into smaller 128 KB stripe sets distributed across all disks in a disk group [1]. It optimizes small-payload write operations to minimize I/O latency and spread rapid concurrent writes across physical devices [1]. Target files utilizing fine-grained striping include Online Redo Logs (ORLs), Control Files, and Flashback Logs [1]. The sources outline Fine-Grained Striping for IFS Applications workloads without specifying a version restriction [1].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "How is Oracle Partitioning supported in IFS Cloud environments and what table partitioning strategies are available?", "a": "Official IFS Cloud technical documentation confirms that Oracle Partitioning is supported ('Y') and verified for IFS Applications 9 & 10, covering table partitioning along with global and local index partitions . Oracle Database provides Range Partitioning for time-series data like audit logs, List Partitioning for discrete values like regional site codes, and Hash Partitioning to prevent I/O hotspots . However, the sources do not provide step-by-step SQL code examples specifically demonstrating range or hash partition creation for IFS Cloud 25R1 . The absence of detailed IFS Cloud 25R1 partitioning code samples is explicitly noted as not covered in the selected sources .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "What SQL query is executed against the ASM instance to calculate total storage capacity and percentage space utilization across mounted disk groups?", "a": "Database administrators connect to the ASM instance (+ASM) and query the V$ASM_DISKGROUP view to retrieve total_mb and free_mb columns for each mounted disk group . By calculating ROUND((1 - (free_mb / total_mb)) * 100, 2), DBAs determine the exact percentage utilization across DATA and RECO groups . This query allows administrators to establish baseline metrics before setting physical disk threshold alerts . The sources outline this ASM query for IFS Applications (IFS Cloud, IFS Applications 10/9) without specifying a version restriction .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "What is the primary operational role of the DATA disk group in Oracle Automatic Storage Management (ASM) and what database assets does it house?", "a": "The DATA disk group serves as the primary operational storage area housing active data files, index tablespaces, system tablespaces (SYSTEM and SYSAUX), temporary files, and online redo log groups . It prioritizes high read and write IOPS performance to process active IFS mid-tier transactions . This disk group layout ensures that active transaction processing runs with high efficiency . The sources describe this DATA disk group configuration for IFS Applications (IFS Cloud, IFS Applications 10/9) without stating a specific database version restriction .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "What is the purpose of the RECO disk group and why are recovery files isolated from primary database files?", "a": "The RECO (or FRA) disk group acts as the dedicated recovery storage area storing archive logs, RMAN backup sets, control file copies, Flashback logs, and multiplexed copies of online redo logs . Isolating recovery files from the DATA disk group prevents heavy backup or archiving operations from competing for disk bandwidth with primary data transactions . This isolation maintains core OLTP performance while guaranteeing recovery capabilities . The sources outline this RECO disk group architecture for IFS Applications (IFS Cloud, IFS Applications 10/9) without imposing a database version constraint .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "What operational roles do 85 percent warning and 95 percent critical storage alert thresholds serve in Oracle Enterprise Manager (OEM)?", "a": "OEM warning thresholds set at 85% capacity utilization alert DBAs to investigate growing data files and plan storage expansions during regular maintenance windows . Critical thresholds set at 95% capacity utilization signify urgent storage pressure requiring immediate administrative intervention to prevent out-of-space transaction halts . Tablespace thresholds monitor logical space in data files, whereas ASM disk group thresholds monitor physical free space across shared storage pools like DATA and RECO . The sources describe this alert threshold architecture for IFS Applications without stating a database version constraint .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "Which PL/SQL package and dictionary view are used to programmatically configure and verify tablespace warning and critical thresholds?", "a": "Database administrators programmatically configure tablespace warning and critical thresholds using the DBMS_SERVER_ALERT.SET_THRESHOLD procedure with the TABLESPACE_SPACE_USAGE metric . Warning parameters are set to 85 percent and critical parameters to 95 percent for specified tablespaces . DBAs verify registered threshold settings by querying the DBA_THRESHOLDS data dictionary view . The sources present this PL/SQL threshold procedure for Oracle databases without placing a version constraint on its usage .", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Storage, ASM and Capacity Management", "q": "Which dynamic performance views do database administrators query inside an ASM instance to inspect file striping and disk group usage?", "a": "Database administrators query V$ASM_FILE and V\\(ASM_ALIAS views while connected to the ASM instance (+ASM) to verify whether specific database files use fine or coarse striping [1]. Disk group capacity metrics, total megabytes, free space, and redundancy models are inspected by querying the V\\)ASM_DISKGROUP view. These views allow DBAs to monitor disk utilization percentages across DATA and RECO groups. The official Oracle documentation documents these ASM views for Oracle Database 19c.", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How do Fast Application Notification (FAN) events and Oracle Notification Service (ONS) assist integrated client connection pools?", "a": "Fast Application Notification (FAN) publishes real time notifications regarding cluster state changes such as UP and DOWN events for nodes, services, and instances [1]. Beginning with Oracle Database 12c Release 2 (12.2), all clients use Oracle Notification Service (ONS) to receive FAN events [1]. Integrated connection pools subscribe to ONS to immediately clean up dead physical connections during outages, eliminating TCP/IP timeout hangs [1]. The sources specify ONS usage as standard for all clients starting with Oracle Database 12c Release 2 (12.2) [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How do private Interconnect network connectivity and Cache Fusion function together in Oracle RAC?", "a": "The private Interconnect is a dedicated high speed network that connects all servers in an Oracle RAC cluster [1]. Cache Fusion transfers database blocks directly between instance SGA memory caches across the Interconnect without writing updates to disk [1]. Direct cross node memory transfer reduces disk I/O latency during transaction processing [1]. The sources describe Cache Fusion and Interconnect mechanics without placing a version restriction on them [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How do runtime connection load balancing goals work in conjunction with the Load Balancing Advisory?", "a": "The Load Balancing Advisory generates performance metrics and recommendations based on service quality or throughput [1]. Service runtime connection load balancing goals are configured using SRVCTL with -rlbgoal SERVICE_TIME or THROUGHPUT, alongside -clbgoal SHORT or LONG [1]. Integrated client pools use these advisory FAN events to direct incoming work requests to the least loaded instances [1]. The sources detail these load balancing parameters for Oracle RAC without stating a specific version limit [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How does High Availability IP (HAIP) technology protect the private Interconnect in Oracle RAC?", "a": "High Availability IP (HAIP) utilizes redundant network interface cards (NICs) across multiple physical adapters to ensure continuous Interconnect connectivity [1]. It guarantees high throughput for internal cluster heartbeats and Cache Fusion memory transfers [1]. If an Interconnect NIC fails, HAIP prevents network outages and keeps Cache Fusion active without session disruption [1]. The sources present HAIP functionality for Oracle RAC environments without restricting it to a single database version [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How does Single Client Access Name (SCAN) handle incoming client connection requests across cluster nodes?", "a": "Single Client Access Name (SCAN) provides a single network name resolving to three IP addresses that remain constant throughout the life of the cluster [1]. Incoming client connections are load balanced across the three SCAN listeners, which redirect requests to local listeners on appropriate nodes [1]. In Oracle Real Application Clusters 12c Release 2 (12.2), SCAN listeners were enhanced to support HTTP protocol awareness for redirecting HTTP clients across nodes [1]. The sources document SCAN routing behavior, noting the HTTP redirection enhancement specifically for Oracle Database 12c Release 2 (12.2) [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "How does every database instance operate in an Oracle RAC active active node clustering environment?", "a": "In an Oracle RAC active active node clustering environment, every node runs its own set of System Global Area (SGA) memory structures and background processes [1]. All nodes actively accept connections and process concurrent transactions from IFS mid-tier application server pools [1]. All cluster instances read from and write to the same shared database files hosted on Oracle Automatic Storage Management (ASM) disk groups [1]. The sources do not state a specific database version constraint for these active active clustering principles [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "What is the primary operational role of Cluster Synchronization Services (CSS) within Oracle Grid Infrastructure?", "a": "Cluster Synchronization Services (CSS) manages node membership in the cluster and continuously detects node responsiveness [1]. If a node fails or loses network communication with the rest of the cluster, CSS handles node eviction to prevent split brain scenarios [1]. This eviction mechanism preserves overall cluster health and data consistency [1]. The sources outline these CSS membership functions without imposing a specific database version limit [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "What is the role of the Global Resource Directory (GRD) in maintaining cache consistency across RAC nodes?", "a": "The Global Resource Directory (GRD) tracks the state, location, and lock status of every cached data block across all active nodes [1]. Global Cache Service (GCS) and Global Enqueue Service (GES) processes coordinate memory buffers and enqueues within the GRD to prevent dirty reads [1]. The memory required by the GRD and Cache Fusion components consumes approximately 10 percent of the total SGA [1]. The sources document these GRD specifications for Oracle RAC without specifying a version restriction [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "Which dynamic performance views are queried to verify private Interconnect network settings across RAC instances?", "a": "Database administrators query V$CLUSTER_INTERCONNECTS and V\\(CONFIGURED_INTERCONNECTS to inspect private Interconnect interface names, IP addresses, and configuration sources [1]. Querying the global GV\\)CLUSTER_INTERCONNECTS view retrieves interconnect entries across all active instances in the cluster simultaneously [1]. These views allow DBAs to verify that Cache Fusion traffic flows over private network adapters [1]. The official Oracle documentation documents these interconnect performance views for Oracle Database 19c [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "RAC and Grid Infrastructure", "q": "Which high availability resources are managed by Cluster Ready Services (CRS) in Oracle Clusterware?", "a": "Cluster Ready Services (CRS) manages high availability resources including Virtual IPs (VIPs), Single Client Access Name (SCAN) listeners, database instances, and services [1]. It automatically restarts failed resources or relocates them across healthy cluster nodes [1]. Configuration data for these managed resources is stored in the Oracle Cluster Registry (OCR) [1]. The sources present these CRS management functions without specifying a database version restriction [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "How does Oracle Data Guard Fast Start Failover (FSFO) automate recovery and what prerequisite feature is mandatory?", "a": "Fast Start Failover (FSFO) uses an independent Observer process to monitor primary database health and execute automatic failover if the primary becomes unreachable. When primary connectivity is lost and the FastStartFailoverThreshold expires, the Observer automatically promotes the standby database. Enabling Flashback Database on both primary and standby databases is strictly mandatory for FSFO operation. The sources describe FSFO mechanics and Flashback prerequisites without imposing a specific database version restriction.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "How does Real Time Redo Apply differ from traditional archive log apply and how does it optimize RPO and RTO?", "a": "Under Real Time Redo Apply, the Log Network Server (LNS) process on the primary transmits redo directly to the Remote File Server (RFS) process on the standby, writing immediately to SRLs. The Managed Recovery Process (MRP0) applies redo directly from SRLs to memory and disk, eliminating lag associated with waiting for log switches. This continuous apply mechanism achieves zero data loss (RPO = 0) and rapid failover (RTO < 5 minutes) for IFS Applications workloads. The sources describe Real Time Apply mechanics for Oracle Database 19c and IFS Applications enterprise environments.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "How is the ORA 16698 error resolved when starting the Data Guard Broker in an Oracle Database 19c environment?", "a": "The ORA 16698 error occurs when the manual LOG_ARCHIVE_DEST_n parameter contains a SERVICE attribute before starting the broker. To resolve the conflict, administrators clear manual archive destinations using ALTER SYSTEM SET LOG_ARCHIVE_DEST_2='' SCOPE=BOTH SID='*'. After clearing manual destinations, the Data Guard Broker is initialized by setting ALTER SYSTEM SET DG_BROKER_START=TRUE SCOPE=BOTH SID='*'. The architecture notes document these specific commands and resolution steps for Oracle Database 19c.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "What are the core differences between the Bronze, Silver, Gold, and Platinum tiers in the Oracle Maximum Availability Architecture (MAA) framework?", "a": "The Bronze tier provides single instance database recovery using backups, while the Silver tier adds local high availability with Oracle RAC. The Gold tier combines local RAC clustering with a remote Oracle Data Guard or Active Data Guard physical standby database to achieve RPO = 0 and RTO < 1 minute. The Platinum tier extends Gold architecture by adding Oracle GoldenGate active active replication and Edition Based Redefinition for zero downtime maintenance. The architecture notes present Gold architecture for Oracle Database 19c, while official Oracle documentation requires Oracle AI Database 26ai or higher for Platinum Option 1.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "What are the fundamental differences between a planned Data Guard switchover and an emergency failover operation?", "a": "A planned switchover is a reversible, two way role transition between primary and standby databases that guarantees zero data loss (RPO = 0) without requiring database recreation. An emergency failover is an irreversible, one way transition triggered during catastrophic primary failure to promote the standby to the primary role. In Maximum Performance mode, an ungraceful failover may incur data loss (RPO > 0) due to unapplied redo logs. The sources present these role transition definitions without restricting them to a single database version.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "What configuration rules govern the setup of Standby Redo Logs (SRLs) in an Oracle Data Guard physical standby environment?", "a": "Standby Redo Logs (SRLs) must be created on both primary and standby databases to support role transitions seamlessly. Each SRL file must be sized to match the Online Redo Logs (ORLs) of the primary database exactly. The minimum number of SRL groups required per thread is calculated using the formula (ORL groups per thread + 1). The sources outline these SRL sizing rules for Oracle Data Guard physical standby setups without specifying a database version limit.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "What performance benefits does Active Data Guard offer when opening a physical standby database in Read Only mode?", "a": "Active Data Guard allows a physical standby database to remain open in READ ONLY mode while the Managed Recovery Process (MRP0) applies redo in real time. Heavy analytical reporting, financial queries, and external BI integrations are offloaded to the standby instance. Offloading query workloads frees CPU and I/O capacity on the primary database to optimize core OLTP transaction performance for IFS Applications. The sources detail Active Data Guard offloading for Oracle Database 19c and IFS Applications workloads.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "What technical guidance do the selected sources provide regarding Oracle Database@Azure cloud network peering and TDE key replication for Data Guard?", "a": "The selected sources do not contain technical network peering steps or TDE vault replication procedures for Oracle Database@Azure cloud deployments. The available sources focus on on-premise and general MAA Data Guard architecture, switchover runbooks, and replication lag thresholds. The absence of specific Oracle Database@Azure configuration procedures is explicitly noted as not covered in the selected sources.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "Which dynamic performance views are queried to verify Data Guard database roles, MRP0 process status, and apply lag?", "a": "Database roles and open modes are verified by querying the database_role and open_mode columns in the V$DATABASE view. The status of the Managed Recovery Process (MRP0) is checked by querying the V\\(MANAGED_STANDBY view. Replication lag metrics including apply lag and transport lag are monitored through the V\\)DATAGUARD_STATS view. The sources outline these verification views for Oracle Data Guard 19c administration.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 6, "title": "Data Guard, MAA Standards and Failover Operations", "q": "Which exact SQL commands are executed in sequence to open a physical standby database in Active Data Guard Read Only mode?", "a": "First, administrators execute ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL to stop active recovery. Next, the database is opened using ALTER DATABASE OPEN. Finally, real time apply is resumed by executing ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT. The sources document this exact SQL command sequence for Active Data Guard without specifying a database version constraint.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "Oracle Data Guard Concepts and Administration, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/sbydb/"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How are Fast Connection Failover (FCF) and Oracle Notification Service (ONS) configured to detect database outages in IFS Applications midtier environments?", "a": "Enterprise IFS Applications deployments utilize Fast Connection Failover (FCF) integrated with Oracle Notification Service (ONS) to detect database node outages instantly [1]. ONS broadcasts real-time FAN events across default port 6200 when instance or service state changes occur [1]. In JDBC Universal Connection Pool (UCP) configurations, FCF is enabled by setting fastConnectionFailoverEnabled to true and specifying SCAN-based ONS nodes [1]. The sources outline these FCF and ONS configuration steps for IFS midtier re-connection testing without restricting them to a specific database version [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How are side effects handled during replay in Transparent Application Continuity versus manual Application Continuity?", "a": "Transparent Application Continuity automatically detects statements with external side effects such as sending email or accessing external URLs and disables replay capture during their execution [1]. Manual Application Continuity allows developers to customize side effect replay or manually disable replay for a request using the disableReplay API in the ReplayableConnection interface [1]. Disabling replay on a connection prevents duplicate execution of unrecoverable external actions following a failover [1]. The sources describe these side effect handling mechanisms for Oracle Database 18c and Oracle Database 19c [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How does server side session draining operate during planned database maintenance?", "a": "Before planned maintenance begins, the database or administrator issues a FAN planned-down event, signaling FAN-aware connection pools to stop issuing new requests on target instances [1]. Active sessions are allowed to finish their executing work within a designated drain_timeout period before the connection is closed [1]. Starting with Oracle Database 18c, the server itself intercepts connection tests and inspects session boundaries to safely drain sessions even without client pool intervention [1]. If work does not complete within the drain_timeout, the stopoption IMMEDIATE terminates remaining sessions to initiate failover [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How does the failover_restore parameter behave in Oracle Database 19c when failovertype AUTO is configured on a database service?", "a": "When -failovertype AUTO is assigned to a service in Oracle Database 19c, the -failover_restore parameter is automatically set to AUTO [1]. This setting automatically restores common initial session states such as NLS settings, time zones, and session context when establishing a new connection on a surviving instance [1]. This automatic restoration prevents application errors caused by lost session environment settings following an outage [1]. The sources present this automatic setting behavior specifically for Oracle Database 19c [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How is a Data Guard switchover failover test validated from an IFS Applications midtier application server?", "a": "To test failover logic, the IFS midtier data source URL is configured with SCAN addresses and ONS configuration properties [1]. An administrator executes the SWITCHOVER TO command in Data Guard Broker (DGMGRL) to swap primary and standby database roles [1]. Midtier log files are then monitored to verify that ONS FAN events were received, broken physical connections were discarded, and active SQL sessions re-attached to the newly promoted primary database without manual restart [1]. The sources document these switchover validation steps in the IFS midtier re-connection testing guide [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "How is a database service configured for Transparent Application Continuity using the srvctl tool in Oracle RAC?", "a": "Using the srvctl tool, Transparent Application Continuity is enabled by setting the service attribute -failovertype AUTO [1]. To ensure full resilience, administrators also configure -failover_restore AUTO to restore session state, -commit_outcome TRUE to activate Transaction Guard, and -notification TRUE to publish FAN events [1]. Parameters such as -failoverretry 30 and -failoverdelay 10 manage reconnection attempts during service relocation or failover [1]. The srvctl syntax and service parameter definitions apply to Oracle Database 18c and Oracle Database 19c deployments [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "What is the main difference between Transparent Application Continuity (TAC) and manual Application Continuity (AC), and in which version was TAC introduced?", "a": "Transparent Application Continuity (TAC) transparently tracks and records session and transactional state without requiring code changes or explicit request boundaries [1]. Manual Application Continuity (AC) requires explicit request boundary declarations, such as beginRequest and endRequest API calls in Java applications [1]. TAC was introduced in Oracle Database 18c and is supported in Oracle Database 19c, whereas manual AC is available starting with Oracle Database 12c Release 1 (12.1) for Java thin drivers [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "Which connection string parameters are recommended to prevent timeout hangs and login storms during client failover?", "a": "Recommended JDBC thin driver connection strings include CONNECT_TIMEOUT, RETRY_COUNT, RETRY_DELAY, and FAILOVER=ON [1]. Setting RETRY_COUNT and RETRY_DELAY allows the client driver to retry connections repeatedly while a service relocates during planned maintenance or failover [1]. Adding TRANSPORT_CONNECT_TIMEOUT, introduced in Oracle Database Release 12.1.0.2, prevents client sessions from hanging on un-responsive network addresses [1]. The sources describe these connection descriptor parameters for Oracle Database 12c Release 1 and later drivers [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "Which database component is mandatory for enabling Application Continuity, and how does it prevent duplicate transaction execution following an outage?", "a": "Application Continuity strictly requires Transaction Guard to be enabled on the database service by setting COMMIT_OUTCOME=TRUE [1]. Transaction Guard assigns a globally unique Logical Transaction ID (LTXID) to every user request to verify whether an in-flight transaction committed before an outage occurred [1]. By checking the commit outcome using the LTXID during failover, Transaction Guard prevents completed transactions from being replayed multiple times [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Application Continuity and Resilience", "q": "Which dynamic performance views and metrics are used to measure protection levels under Application Continuity?", "a": "Protection levels under Application Continuity are monitored using statistics in V\\(SESSTAT, V\\)SYSSTAT, and V\\(SERVICE_STATS views, which are also stored in Automatic Workload Repository (AWR) reports [1]. Key metrics include cumulative begin requests, cumulative end requests, cumulative user calls in requests, and cumulative user calls protected [1]. An application is fully protected when cumulative user calls protected equals cumulative user calls in requests and the values are greater than zero [1]. Monitoring via V\\)SERVICE_STATS is documented specifically for Oracle Database 19c and later versions [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "How do database administrators inspect the actual runtime execution plan and row counts of a cached SQL statement in memory?", "a": "Database administrators retrieve actual cached execution plans by executing the DBMS_XPLAN.DISPLAY_CURSOR function with the format parameter set to ALLSTATS LAST for a target SQL ID [1]. This output displays the actual execution steps along with Estimated Rows (E-Rows) and Actual Rows (A-Rows) for each operation [1]. Large discrepancies between estimated and actual row counts signal stale or missing table statistics that require gathering fresh statistics with DBMS_STATS [1]. The sources describe this execution plan profiling workflow for Oracle Database 19c and IFS Applications workloads [1].", "sources": [{"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "How do sga_target, pga_aggregate_target, open_cursors, and processes parameters prevent database memory and capacity failures?", "a": "Setting sga_target enables Automatic Shared Memory Management (ASMM) to dynamically allocate memory to the Buffer Cache and Shared Pool, preventing hard parses and disk I/O bottlenecks [1]. The pga_aggregate_target parameter manages session work areas for sorts and hash joins, preventing excessive temporary tablespace spilling during batch jobs [1]. Proper tuning of processes prevents ORA-00020 connection rejection errors, while open_cursors prevents ORA-01000 cursor leak errors in Java connection pools [1]. The sources detail these parameter tuning functions for IFS Applications (IFS Cloud and IFS Applications 10/9) without specifying a version restriction [1].", "sources": [{"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "How does Active Session History (ASH) sampling work in memory, and how does it differ from hourly AWR snapshots?", "a": "Active Session History (ASH) samples active session state and wait event data every second directly into the SGA ring buffer (v$active_session_history) [1]. Unlike hourly AWR snapshots that average performance metrics over longer intervals, ASH captures short-lived, transient I/O spikes, locking conflicts, and runaway SQL executions in real time [1]. The MMON background process periodically flushes in-memory ASH samples to disk tables (dba_hist_active_sess_history) for historical analysis [1]. The sources describe ASH sampling mechanics for Oracle databases without placing a version constraint on its usage [1].", "sources": [{"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "How does the Automatic Database Diagnostic Monitor (ADDM) analyze database performance bottlenecks and make proactive recommendations?", "a": "The Automatic Database Diagnostic Monitor (ADDM) automatically evaluates performance metrics between consecutive AWR snapshots by focusing on total DB Time [1]. Using a top-down tree structure, it analyzes system performance from high-level CPU and wait-time distributions down to specific SQL statements, schema objects, and hardware resources while ruling out non-problem areas [1]. It then generates prioritized tuning recommendations covering infrastructure adjustments, database parameter modifications, and SQL optimizations for IFS Applications workloads [1]. The sources describe ADDM mechanics without specifying a database version restriction [1].", "sources": [{"title": "ADDM Report Analysis & Proactive Recommendations", "url": ""}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "What causes row level locking enqueue contention in IFS Applications, and how is it identified using wait events?", "a": "Row level locking enqueue contention is identified by the enq: TX - row lock contention wait event when sessions attempt to modify rows locked by uncommitted transactions [1, 2]. In IFS Applications environments, this contention typically occurs during concurrent updates to customer orders, inventory balances, or financial ledgers without proper application level queuing [2]. The session holding the row lock must issue a COMMIT or ROLLBACK to release the TX enqueue and allow waiting sessions to proceed [1, 2]. The sources outline this row lock enqueue behavior for Oracle Database 18c and 19c enterprise workloads [1, 2].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "What is the relationship between DB Time and Elapsed Time in AWR reports, and what does it indicate when DB Time exceeds Elapsed Time?", "a": "In AWR reports, Elapsed Time measures wall-clock time between snapshots, whereas DB Time represents the cumulative active time spent by user sessions on CPU and non-idle wait events [1]. When DB Time significantly exceeds Elapsed Time during a peak operational window, it indicates high concurrency and severe resource or locking contention across database threads [1]. Tracking per-second metrics alongside DB Time helps database administrators identify whether bottlenecks stem from OLTP transaction spikes or unoptimized full table scans in IFS Applications [1]. The sources present these AWR performance metrics for IFS Applications (IFS Cloud and IFS Applications 10/9) without a specific database version limit [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "What reference information is provided in Section C.3 Descriptions of Wait Events in the official Oracle Database 18c Reference documentation?", "a": "Section C.3 Descriptions of Wait Events in the Oracle Database 18c Reference serves as a comprehensive catalog describing why database processes pause during execution [1]. It details operational causes, wait time durations, and parameter definitions for I/O waits, buffer cache locks, enqueue events, and cluster communication [1]. DBAs query the V$EVENT_NAME view or consult this section to interpret system wait statistics during performance troubleshooting [1]. The official Oracle documentation documents this wait event reference catalog specifically for Oracle Database 18c [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "What wait events indicate mutex and latch contention in the Shared Pool and Library Cache during heavy query parsing?", "a": "Mutex and latch contention during heavy SQL parsing is indicated by wait events such as cursor: mutex S, cursor: mutex X, cursor: pin S wait on X, cursor: pin X, and library cache: mutex X [1]. These wait events occur when high volume mid-tier connections generate excessive hard parsing or execute unshared SQL statements that hammer shared pool hash buckets [1, 2]. Holding exclusive mutexes or latches blocks concurrent sessions from accessing or updating cursor objects in memory [1, 2]. The sources document these cursor and library cache wait events in the Oracle Database 18c reference catalog [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "Which AWR report script is used to compare performance baseline metrics before and after applying an Oracle Release Update patch?", "a": "Database administrators generate AWR Compare Period reports using the awrddrpt.sql script for single-instance databases or awrddrpi.sql for Oracle RAC environments to evaluate system stability after applying an Oracle Release Update [1]. The report provides side-by-side metric comparisons between equal-duration baseline and post-patch snapshot windows [1]. DBAs analyze load profile changes, top wait event shifts, SQL execution plan changes, and CPU or memory utilization to detect performance regressions [1]. The sources present this AWR comparison workflow for Oracle Database 19c and IFS Applications environments [1].", "sources": [{"title": "ADDM Report Analysis & Proactive Recommendations", "url": ""}]}, {"chapter": 8, "title": "Performance Management and Tuning", "q": "Why can an increase in the db file sequential read wait event indicate an unselective or improper index usage rather than a missing index?", "a": "The db file sequential read wait event captures single-block read operations, which occur when traversing B-tree index structures or fetching table rows via ROWID [1, 2]. When a query predicate is unselective and matches a large percentage of rows in a table, using an index forces Oracle to perform thousands of individual single-block I/O reads rather than a multi-block scan [1]. This unselective index traversal creates severe disk read bottlenecks that are far more costly than a full table scan [1]. The sources describe these wait event mechanics for Oracle Database 18c and 19c reference environments [1, 2].", "sources": [{"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}, {"title": "AWR Performance Metrics Interpretation", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How are OEM Incident Rule Sets and Blackout calendars configured to manage notification routing and suppress false alarms?", "a": "Incident Rule Sets define automated responses based on target criteria, sending email alerts, executing corrective OS scripts, or creating external support tickets [1]. Administrative Blackout calendars temporarily pause metric collection and alert generation during scheduled maintenance windows [1]. Suppressing alerts during maintenance prevents false alarms from flooding operation teams during routine IFS environment updates [1]. The sources describe these rule sets and blackout calendars for OEM monitoring without restricting them to a single database version [1].", "sources": [{"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How are messaging pipelines and active subscribers managed using the Oracle Queues interface in IFS Cloud 26R2?", "a": "The Oracle Queues page in Solution Manager allows administrators to start, stop, and clean up asynchronous Oracle Advanced Queuing message tables. The Oracle Queue Subscribers view lists active queue consumers and allows supervisors to remove obsolete subscriber entries safely. Managing these queues ensures smooth background message flow and data streaming across IFS modules. The sources present these Oracle Advanced Queuing management pages specifically for IFS Cloud 26R2.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How do Application Monitoring Metrics (AMM) and the Application Monitoring Console (AppMon) evaluate health statuses in IFS Cloud 26R2?", "a": "Application Monitoring Metrics (AMM) evaluate raw diagnostic data against threshold expressions to produce OK, Warning, Critical, or Unknown status codes. The Application Monitoring Console (AppMon) in Solution Manager visualizes these metric statuses and provides a Show Alarms Only filter to isolate failing items. The Foundation1 Monitoring scheduled task runs daily to update metric statuses across application components. The sources outline AMM concepts and the AppMon console specifically for IFS Cloud 26R2.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How does Streams functionality in IFS Cloud 26R2 notify users when background jobs and scheduled tasks complete?", "a": "Streams functionality sends notifications via the Transaction_SYS.Process_All_Pending scheduler when Transaction_SYS.Deferred_Call single-run jobs or Batch_SYS.New_Batch_Schedule tasks finish. Notifications are enabled using the stream_msg_on_completion_ and stream_notes_ parameters during job creation. Developers can customize notification messages using the Transaction_SYS.Modify_Stream_Notification Hooking API. The sources detail Streams notification mechanics specifically for IFS Cloud 26R2.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How does the Response Time Detail View Dashboard in Kibana display projections and entities performance metrics?", "a": "The Response Time Detail View Dashboard in Kibana displays execution metrics for projections and entities once log data views are established. The dashboard automatically sorts performance records from slowest response times to fastest response times. Ordering metrics by response duration enables technical teams to identify and troubleshoot slow running operations quickly. The sources document this Kibana dashboard feature specifically for IFS Cloud 25R1.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "How does the promotion logic from metric Events to actionable Incidents work within the OEM event management architecture?", "a": "Oracle Management Agents continuously sample target metrics and generate an Event whenever a performance indicator crosses a warning or critical threshold [1]. An Incident Rule Set evaluates the incoming Event and automatically promotes it to an Incident if it requires administrative intervention [1]. Promoting Events to Incidents ensures that technical teams track and resolve high priority operational problems systematically [1]. The sources outline this event promotion lifecycle for OEM monitoring without placing a version restriction on it [1].", "sources": [{"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "What are the core operational roles of OMS, OMR, and OMA infrastructure components within Oracle Enterprise Manager (OEM) Cloud Control?", "a": "Oracle Management Service (OMS) is a WebLogic based middle-tier application that processes incoming telemetry and serves the Cloud Control management console. Oracle Management Repository (OMR) is a dedicated Oracle database storing configurations and metric histories within the SYSMAN schema. Oracle Management Agent (OMA) runs as a standalone process on managed target nodes to gather performance metrics and upload them to OMS over TCP port 3872. The sources describe these infrastructure components for OEM 13c/14c setups without specifying a database version restriction.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "What components comprise the EFK logging stack in IFS Cloud 25R1 Remote Deploy environments and how long are log records retained?", "a": "In IFS Cloud 25R1 Remote Deploy environments, log monitoring is implemented using an EFK logging stack composed of Elasticsearch, Fluentd, and Kibana. Fluentd collects container and application logs across nodes, while Elasticsearch stores log data for a mandatory seven-day retention cycle. A daily curator cronjob automatically deletes indices older than seven days to manage storage capacity. The sources present this EFK logging stack specifically for IFS Cloud 25R1 Remote Deploy deployments.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "Which administrative actions and agent lifecycle management operations are performed using the emctl command line utility?", "a": "The emctl command line utility is used on the OMS host to stop, start, or check the status of WebLogic middle-tier services and repository connections. On target nodes, administrators use emctl status agent to verify agent health and ping connectivity to the OMS server. Running emctl upload agent forces immediate metric uploads to OMS, while emctl secure agent synchronizes security certificates across nodes. The sources present these emctl command functions for OEM 13c/14c agent administration without imposing a specific version limit.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Monitoring, Alerting and Incident Management", "q": "Which default log categories and retention settings are managed within the Server Alert Log Categories page in IFS Cloud 26R2?", "a": "The Server Alert Log Categories page allows administrators to configure categories including Ddl Audit, Debug, Deployment, Event errors, Server Errors (ORA errors), and Sql Injections. Each log category features an Enable toggle, a Cleanup toggle, and a configurable Days to keep retention setting. Managing these category settings enables administrators to capture server side errors while automatically purging aged logs to preserve space. The sources document these alert log categories specifically for IFS Cloud 26R2.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "OEM Agent Administration across Nodes", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "How can database administrators remap recovered tables to different schemas or tablespaces during RMAN table recovery?", "a": "During table recovery, administrators can use the REMAP TABLE clause to rename recovered tables or map them to a different schema in the target database [1]. The REMAP TABLESPACE clause imports recovered tables or table partitions into a target tablespace different from their original location [1]. Named constraints and indexes are not imported when using the REMAP TABLE or REMAP TABLESPACE options [1]. The sources describe these remapping options for RMAN table recovery operations [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "How does RMAN perform table level point in time recovery (PITR) using an auxiliary instance?", "a": "When executing the RECOVER TABLE command, RMAN automatically checks for sufficient space on the target host to store temporary files for an auxiliary instance [1]. It restores necessary backups to the auxiliary instance, recovers the specified tables to the target point in time, and generates a Data Pump export dump file [1]. By default, RMAN automatically imports the dump file into the target database unless the NOTABLEIMPORT clause is specified [1]. The sources present this automated table recovery process for Oracle database administration [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What RMAN commands were deprecated due to the deprecation of the Data Recovery Advisor (DRA) feature in Oracle Database 19c?", "a": "Starting in Oracle Database 19c, the Data Recovery Advisor (DRA) feature is deprecated [1]. This deprecation includes the deprecation of the LIST FAILURE, ADVISE FAILURE, REPAIR FAILURE, and CHANGE FAILURE RMAN commands [1]. Database administrators no longer have access to these commands, and there is no replacement feature for DRA [1]. The sources document this deprecation specifically for Oracle Database 19c [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What administrative pre deployment checklist rule was established following the November 11, 2026 incident review?", "a": "Following an unexpected system outage reported during the 2026 incident preparation meeting, an administrative rule was added requiring verification of active background jobs prior to software deployment. The deployment checklist mandates confirming that no uncompleted or stuck batch jobs remain active before starting a release [1]. This pre deployment check prevents database objects from entering an INVALID state and avoids queue message backlogs during updates [1]. The incident review document details this rule for IFS software deployment procedures [1].", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What database compatibility requirements govern duplicating a Pluggable Database (PDB) to an existing CDB using RMAN?", "a": "The DUPLICATE PLUGGABLE DATABASE command is used to duplicate a PDB to an existing CDB, a feature introduced in Oracle Database 18c [1]. To duplicate a PDB to an existing CDB, the COMPATIBLE initialization parameter on both the source CDB and destination CDB must be set to 18.0.0 or higher [1]. Additional prerequisites require both source and destination CDBs to use local undo, and the destination CDB must be open in read write mode [1]. The sources state these requirements specifically for Oracle Database 18c and higher [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What is the recommended procedure for database point in time recovery when taking storage snapshots in Oracle Database 19c?", "a": "In Oracle Database 19c, the RECOVER SNAPSHOT TIME method of recovering a database to a point in time using a storage snapshot is deprecated [1]. Instead, Oracle recommends executing ALTER DATABASE BEGIN/END BACKUP before and after creating the storage snapshot of the data files on a running database [1]. Point in time recovery is then performed using RECOVER UNTIL TIME to a specific timestamp or SCN after the END BACKUP completion time [1]. Archived redo logs must be separately backed up and restored for recovery operations [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What monitoring metric and alert threshold is recommended to detect message backlogs in Oracle Advanced Queues (AQ)?", "a": "When asynchronous processors hang, messages accumulate inside Oracle Advanced Queues (AQ) message tables [1]. Metric data for queue depth is gathered under the ifs_aq metric, and an AQ backlog alarm is recommended when ready message counts remain high for an extended period [1]. Defining an alert threshold for pending messages provides an early warning signal that background queue processors have stalled [1]. The incident review document outlines this AQ backlog signal for IFS Cloud infrastructure monitoring [1]. animate", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What prerequisites and restrictions apply when performing RMAN FLASHBACK DATABASE on a Pluggable Database (PDB)?", "a": "To perform flashback operations on a PDB, the COMPATIBLE initialization parameter must be set to 12.2.0.0 or higher, and RMAN must connect to the root as a common user [1]. The target PDB must be closed during the flashback operation while other PDBs can remain open and operational [1]. Flashback operations on a proxy PDB are not supported in Oracle Multitenant environments [1]. The sources detail these PDB flashback prerequisites and restrictions for Oracle Database 12c Release 2 (12.2) and higher [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "What technical details do the selected sources provide regarding RMAN RECOVER TABLE options for Oracle AI Database 26ai?", "a": "The selected sources do not contain technical details, command syntax, or specific rules for RMAN RECOVER TABLE operations in Oracle AI Database 26ai [1]. The available documentation details table recovery parameters for Oracle Database 12c, 18c, and 19c releases [1]. The absence of Oracle AI Database 26ai table recovery specifications is explicitly noted as not covered in the selected sources [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Backup, Recovery and Operational Practice", "q": "Which read only SQL queries are recommended to inspect Oracle Scheduler jobs and alert logs during post incident reviews without requiring pack licenses?", "a": "To analyze Oracle Scheduler job execution history during post incident reviews, database administrators query the owner, job_name, status, actual_start_date, and run_duration columns from dba_scheduler_job_run_details [1]. Oracle alert log records containing ORA errors or deadlocks are queried from the v$diag_alert_ext view filtered by originating_timestamp [1]. These queries require no Oracle Diagnostics or Tuning Pack licenses and do not grant new privileges to monitoring users [1]. The sources present these read only queries in the post incident review preparation guidelines [1].", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}]}]}, "teknik-gelistirim-tr": {"language": "tr", "items": [{"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS Applications orta katman oturumlarının yeniden kullanımı için Shared Pool ve Buffer Cache bileşenleri nasıl bir işlev görür?", "a": "System Global Area (SGA) bünyesindeki Shared Pool; ayrıştırılmış SQL, PL/SQL kodlarını, yürütme planlarını ve veri sözlüğü bilgilerini saklayarak IFS orta katman oturumlarının hızlı yeniden kullanımını sağlar [1]. Buffer Cache ise diskten okunan veri bloklarını önbelleğe alarak frequent sorguların yanıt sürelerini optimize eder [1]. sga_target altındaki dinamik tahsisat, bu iki bileşeni operasyonel iş yükü taleplerine göre dengeler [1]. Kaynaklar bu SGA bellek bileşenlerinin işlevleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Memory Architecture Tuning (sga_target & pga_aggregate_target)", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS Applications ve IFS Cloud veritabanı altyapısında sga_target parametresinin ayarlanması hangi bellek havuzlarını dinamik olarak dengeler ve sisteme nasıl katkı sağlar?", "a": "sga_target parametresinin sıfır olmayan bir değere ayarlanması Otomatik Paylaşılan Bellek Yönetimini (ASMM) etkinleştirerek Buffer Cache, Shared Pool, Large Pool ve Java Pool bellek havuzlarının boyutlarını dinamik olarak dengeler [1]. Shared Pool ayrıştırılmış SQL ve PL/SQL kodlarını saklarken, Buffer Cache veritabanı bloklarını önbelleğe alır [1]. Bu dinamik akortlama, IFS Applications (IFS Cloud ve IFS Applications 10/9) iş yüklerinde sabit ayrıştırma (hard parse) ve disk I/O darboğazlarını önler [1]. Kaynaklar bu ASMM parametre tanımları için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Memory Architecture Tuning (sga_target & pga_aggregate_target)", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS Cloud 25R1 ve 26R2 mimarisi için Oracle 19c veritabanı depolama tier ve sunucu gereksinimleri hakkında kaynaklar hangi detayları vermektedir?", "a": "Seçilen kaynaklar içerisinde IFS Cloud 25R1 ve IFS Cloud 26R2 sürümlerine özel Oracle 19c veritabanı depolama tier ve sunucu kapasite gereksinimlerine dair somut teknik veriler bulunmamaktadır [1]. Kaynaklar yalnızca IFS Applications (IFS Cloud, IFS Applications 10/9) platformlarının kritik ERP, EAM ve FSM operasyonlarında Oracle veritabanı arka uçlarına dayandığını belirtmektedir [1]. Kaynakların kapsamadığı bu sürüme özel depolama ve donanım boyutlandırma detayları kaynaklarda yer almadığı için açıkça belirtilmiştir [1].", "sources": [{"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS Enterprise Oracle Architecture & DBA Eğitim Programı oryantasyonunda müfredat ve ders planı nasıl yapılandırılır?", "a": "Program oryantasyonunda müfredat, veritabanı yöneticilerinin hedeflerini mimari kılavuzlar ve teknik ders başlıklarıyla hizalayacak şekilde yapılandırılır [1, 2]. Eğitim programı multitenant izolasyonu, RAC kümelemesi, ASM depolama yönetimi, Data Guard felaket kurtarma ve AWR/ASH performans teşhisi gibi temel modülleri kapsar [1, 3]. Bu yapılandırma kurumsal veritabanı yöneticileri için kademeli bir öğrenme yol haritası sunar [1]. Kaynaklar bu eğitim yapısını IFS Enterprise Oracle Architecture & DBA Training Program kapsamına özgü olarak sunmaktadır [1, 2].", "sources": [{"title": "Chapter 1 Core Topics Overview", "url": ""}, {"title": "IFS Oracle DBA Training Setup", "url": ""}, {"title": "IFS Applications & Cloud Oracle Infrastructure Architecture Guidelines", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS ortamlarında adanmış Pluggable Database (PDB) yapıları (PDB$SEED ve Kullanıcı PDB'leri) ne amaçla kullanılır?", "a": "PDB$SEED yapısı yeni pluggable veritabanları oluşturmak için sistem tarafından sağlanan şablon bir veritabanı olarak görev yapar [1]. Kullanıcı PDB'leri ise DEV, TEST ve PROD gibi ayrı IFS uygulama örneklerini aynı sunucu donanımı üzerinde izole etmek amacıyla oluşturulur [1]. Bu yapı sayesinde PDB durumları, konteyner bağlamları ve şema nesneleri veritabanı seviyesinde ayrıştırılır [1]. Kaynaklar bu PDB kullanım amaçları için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Chapter 1 Core Topics Overview", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS veritabanı ortamlarında pga_aggregate_target parametresi hangi işlemler için kullanılır ve yetersiz ayarlanması durumunda ne gibi sorunlar yaşanır?", "a": "pga_aggregate_target parametresi, tüm oturumlar genelinde tahsis edilen toplam Program Global Area (PGA) belleği için küresel bir hedef belirler [1]. Oracle, sıralama (ORDER BY), hash join ve bitmap birleştirme iş alanlarına ayrılan belleği dinamik olarak kontrol ederek bu limit dahilinde tutar [1]. Doğru yapılandırma, ağır toplu iş raporları sırasında geçici tablespace (temp tablespace) alanına aşırı veri taşmasını engeller [1]. Kaynaklar bu PGA parametre ayarı için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Memory Architecture Tuning (sga_target & pga_aggregate_target)", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS veritabanı yaşam döngüsünde Release Update (RU) ve Release Update Revision (RUR) yama stratejileri nasıl tanımlanır?", "a": "Release Update (RU), güvenlik açıklarını, yüksek değerli hata düzeltmelerini ve kritik kararlılık geliştirmelerini içeren üç aylık birikimli bir yamadır [1]. Release Update Revision (RUR) ise yeni işlevsel hata düzeltmesi eklemeden mevcut bir RU için kritik güvenlik ve regresyon düzeltmeleri sunarak RU ömrünü uzatır [1]. Üretim dışı ortamlarda (DEV ve TEST) RU tercih edilirken, üretim (PROD) ortamlarında kararlılık için RUR uygulanır [1]. Kaynaklar bu yama yaşam döngüsü tanımları için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Chapter 1 Core Topics Overview", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "IFS veritabanı örneklerinde processes başlangıç parametresinin yetersiz ayarlanması hangi hataya yol açar ve bağlantı havuzlarını nasıl etkiler?", "a": "Statik bir başlangıç parametresi olan processes, Oracle veritabanı örneğine aynı anda bağlanabilecek maksimum işletim sistemi kullanıcı süreci sayısını tanımlar [1]. Her adanmış orta katman bağlantı havuzu, arka plan süreçleri (PMON, DBWn, LGWR) ve veritabanı yöneticisi oturumu bir süreç yuvası tüketir [1]. Parametrenin çok düşük ayarlanması ORA-00020: maximum number of processes exceeded hatasına yol açarak orta katman sunucularının yeni oturum açmasını engeller [1]. Kaynaklar bu parametre tanımı için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "Session & Cursor Capacity Parameter Tuning (open_cursors & processes)", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "Oracle çok kiracılı (Multitenant) veritabanı mimarisinde CDB$ROOT kök konteyner yapısının temel işlevi ve yönetim sorumlulukları nelerdir?", "a": "CDB$ROOT tekil kök konteyner veritabanı, arka plan süreçlerini, paylaşılan sistem metadatasını ve küresel belleği yönetir [1]. Ortak kullanıcı hesaplarını, sistem metadatasını ve küresel veritabanı başlangıç parametrelerini saklar [1]. Bu yapı sayesinde farklı IFS uygulama ortamları ortak veritabanı altyapısını paylaşabilir [1]. Kaynaklar bu CDB$ROOT mimari tanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Chapter 1 Core Topics Overview", "url": ""}]}, {"chapter": 1, "title": "Bölüm 1: Program Oryantasyonu ve IFS Cloud Oracle Altyapı Mimarisi", "q": "Private SQL Area yönetimi için open_cursors parametresi nasıl bir rol oynar ve hangi kapasite hatasını önler?", "a": "Dinamik open_cursors parametresi, tek bir oturumun Private SQL Area içinde aynı anda açık tutabileceği maksimum imleç sayısını belirler [1]. IFS ortamındaki Java/JDBC bağlantı havuzları gibi orta katman çatıları yürütme hızını artırmak için ifade tanıtıcılarını önbelleğe alır [1]. Parametrenin yeterince yüksek ayarlanması imleç sızıntılarını önleyerek ORA-01000: maximum open cursors exceeded hatasını engeller [1]. Kaynaklar bu parametre için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Session & Cursor Capacity Parameter Tuning (open_cursors & processes)", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Aynı konteyner örneğinde çalışan kardeş PDB'leri etkilemeden gerçekleştirilebilecek bağımsız yaşam döngüsü operasyonları nelerdir?", "a": "Veritabanı yöneticileri, aynı CDB bünyesinde çalışan kardeş PDB'lerdeki operasyonları aksatmadan bireysel bir PDB'yi çıkarabilir (unplug), klonlayabilir (clone) veya silebilir (drop) [1]. Bu bağımsız yaşam döngüsü operasyonları sayesinde diğer IFS ortamlarının çalışması kesintiye uğramaz [1]. Böylece veritabanı yönetim yükü önemli ölçüde azalır [1]. Kaynaklar bu yaşam döngüsü operasyonları için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Bir PDB içinde oturum konteyner izolasyonunu ve aktif oturumları doğrulamak için hangi SQL sorguları çalıştırılır?", "a": "Mevcut oturumun konteyner bağlamını ve id bilgisini doğrulamak için sys_context('USERENV', 'CON_NAME') ve sys_context('USERENV', 'CON_ID') fonksiyonları DUAL tablosundan sorgulanır [1]. PDB'ler genelindeki aktif oturum dağılımını ve durumlarını incelemek için ise v$session görünümü con_id, username ve status sütunlarına göre gruplanarak sorgulanır [1]. Bu doğrulama adımları oturumların doğru PDB bağlamında çalıştığını gösterir [1]. Kaynaklar bu doğrulama sorguları için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "IFS Applications ortamlarında Kullanıcı PDB'leri (User PDBs) hangi verileri barındırır ve ne amaçla kullanılır?", "a": "Kullanıcı PDB'leri, IFS Applications için gerekli olan kullanıcı veri şemalarını, tablespace yapılarını ve uygulamaya özel metadataları barındıran adanmış pluggable veritabanlarıdır [1]. Production, Test veya Development gibi bireysel IFS uygulama örneklerini birbirinden tamamen izole etmek için kullanılır [1]. Bu izolasyon sayesinde veritabanı düzeyinde uygulama şemaları ayrıştırılır [1]. Kaynaklar Kullanıcı PDB'leri için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "IFS Applications ortamlarında orta katman (mid-tier) bağlantı havuzlarının PDB ile etkileşimi mantıksal izolasyonu nasıl korur?", "a": "Orta katman bağlantı havuzları yalnızca kendilerine atanan PDB servisi ile etkileşime girer [1]. Bu işlemsel bağlam anahtarlaması sayesinde Development veya Testing gibi üretim dışı örneklerdeki oturumların Production şema nesnelerine erişmesi ya da bunları değiştirmesi engellenir [1]. Böylece farklı IFS uygulama aşamaları aynı fiziksel donanımda güvenle çalıştırılır [1]. Kaynaklar bu bağlantı havuzu izolasyonu için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Oracle Multitenant mimarisinde CDB$ROOT kök konteyner veritabanı hangi temel bileşenleri ve kaynakları yönetir?", "a": "CDB$ROOT kök konteyner veritabanı Oracle sistem metadatasını, ortak kullanıcı hesaplarını ve küresel veritabanı başlangıç parametrelerini saklar [1]. Ayrıca arka plan süreçlerini, paylaşılan sistem metadatasını ve küresel veritabanı belleğini yönetir [1]. Bu mimari sayesinde farklı IFS uygulama ortamları ortak veritabanı altyapısını verimli bir şekilde paylaşabilir [1]. Kaynaklar bu CDB$ROOT mimari tanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Oracle Multitenant yapısında Pluggable Database (PDB) izolasyonu veri sözlüğü (data dictionary) düzeyinde nasıl sağlanır?", "a": "CDB$ROOT ortak sistem metadatasını yönetirken, her PDB kullanıcı tarafından oluşturulan tablolar, indeksler ve uygulama şemaları için kendi özel veri sözlüğünü (private data dictionary) korur [1]. Her PDB, bağlı olan orta katman uygulamasına bağımsız bir veritabanı gibi hizmet verir [1]. Bu özel veri sözlüğü yapısı sayesinde farklı ortamların metadataları birbirine karışmaz [1]. Kaynaklar bu veri sözlüğü izolasyonu için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "PDB seviyesinde bellek kullanımını sınırlandırmak için hangi parametreler kullanılır ve bu sınırlandırma ne sağlar?", "a": "PDB seviyesinde sga_min_size, sga_target ve pga_aggregate_limit parametreleri yapılandırılarak bellek kotaları belirlenir [1]. Bu bellek sınırları, tek bir konteynerdeki kontrolden çıkmış sorguların sunucudaki paylaşılan belleği tüketmesini engeller [1]. Bu sayede birincil işlem iş yükü kardeş PDB'lerin bellek kullanımından korunur [1]. Kaynaklar bu PDB bellek sınırlandırma parametreleri için belirli bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Pluggable veritabanı oluşturma süreçlerinde PDB$SEED yapısının görevi ve kullanım amacı nedir?", "a": "PDB$SEED yapısı, sistem tarafından sağlanan şablon bir Pluggable Database (PDB) olarak görev yapar [1]. Yeni IFS ortamları için hızlı bir şekilde ek pluggable veritabanları oluşturmak amacıyla kullanılır [1]. Bu şablon mekanizması veritabanı devreye alma süreçlerini hızlandırır [1]. Kaynaklar PDB$SEED yapısının işlevi için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Veritabanı yöneticisi CDB root bağlamından hedef bir IFS PDB ortamını açmak ve konteyner bağlamını değiştirmek için hangi SQL komutlarını kullanır?", "a": "Hedef veritabanını açmak için ALTER PLUGGABLE DATABASE ifsprod OPEN komutu, oturum konteyner bağlamını değiştirmek için ise ALTER SESSION SET CONTAINER = ifsprod komutu kullanılır [1]. Mevcut veritabanı konteyner durumları ise v$pdbs görünümü sorgulanarak doğrulanır [1]. Bu komutlar multitenant yapıda güvenli bağlam geçişi sağlar [1]. Kaynaklar bu SQL komut dizilimleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Container Database (CDB) Administration", "url": ""}]}, {"chapter": 2, "title": "Bölüm 2: Multitenant Veritabanı Yönetimi: CDB ve PDB İzolasyonu", "q": "Üretim dışı PDB iş yüklerinin Production performansını olumsuz etkilemesini önlemek için PDB Resource Manager profilleri neleri düzenler?", "a": "PDB Resource Manager profilleri, PDB başına CPU paylarını, paralel yürütme kuyruklarını ve oturum sınırlarını özel olarak tahsis eder [1]. Ağır test betiklerinin veya toplu işlerin kaynakları tüketmesini engelleyerek üretim ortamının performansını korur [1]. Böylece çekirdek üretim iş yükleri kaynak yetersizliğinden korunmuş olur [1]. Kaynaklar PDB Resource Manager profilleri için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Pluggable Database (PDB) Isolation & Operations", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "CDB$ROOT ve tüm PDB'lerde uygulanan yama seviyeleri ve SQL yama geçmişi hangi veri sözlüğü görünümlerinden doğrulanır?", "a": "Veritabanı yöneticileri CDB$ROOT ve tüm PDB yapılarında registry$history ve dba_registry_sqlpatch veri sözlüğü görünümlerini sorgular [1]. Bu sorgular sayesinde uygulanan RU veya RUR seviyeleri, yama kimlikleri ve SQL yama uygulama durumları doğrulanır [1]. Başarısız veya eksik kalan yama adımları bu görünümler üzerinden tespit edilir [1]. Kaynaklar bu veri sözlüğü görünümleri için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Grafik arayüz üzerinden veritabanı yükseltme işlemlerini yürütmek için hangi resmî Oracle aracı kullanılır?", "a": "Grafiksel arayüz üzerinden adım adım veritabanı yükseltme operasyonlarını yönetmek için Database Upgrade Assistant (DBUA) aracı kullanılır [1]. DBUA, yükseltme adımlarını görsel bir sihirbaz üzerinden yapılandırıp çalıştırmaya imkan tanır [1]. Resmî kılavuz DBUA aracını Oracle Database 19c yükseltme kılavuzunda sunmaktadır [1].", "sources": [{"title": "Oracle Database Database Upgrade Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/upgrd/"}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "IFS Applications bakım pencerelerinde yama stratejisinin üretim (PROD) ve üretim dışı (DEV/TEST) ortamlara dağıtımı nasıl planlanır?", "a": "Ana IFS güncelleme döngülerinde yeni işlevsel düzeltmeleri test etmek için üretim dışı ortamlarda (DEV ve TEST) Release Update (RU) uygulanır [1]. Üretim (PROD) ortamlarında ise yürütme planı kararlılığını korumak ve yalnızca kritik güvenlik düzeltmelerini almak amacıyla Release Update Revision (RUR) tercih edilir [1]. Bu hizalama sayesinde bakım pencerelerinde beklenmeyen performans değişiklikleri önlenir [1]. Kaynaklar bu yama dağıtım stratejisini Oracle Database 19c ve IFS Applications 10/9 ortamlarına uygulamaktadır [1].", "sources": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Oracle Database 19c resmî yükseltme kılavuzunda manuel yükseltme ve veri taşıma için hangi alternatif araçlar yer almaktadır?", "a": "Resmî yükseltme kılavuzu manuel yükseltme operasyonları için Parallel Upgrade Utility aracını tanımlamaktadır [1]. Veri taşıma ve aktarım yöntemleri için ise Oracle Data Pump altyapısı sunulmaktadır [1]. Bu araçlar yükseltme sürecinde alternatif veya tamamlayıcı yöntemler olarak kullanılır [1]. Resmî dokümantasyon bu kılavuz detaylarını Oracle Database 19c sürümüne özgü olarak sunmaktadır [1].", "sources": [{"title": "Oracle Database Database Upgrade Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/upgrd/"}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Oracle Database 19c veritabanı yükseltme süreçlerinde AutoUpgrade aracı hangi işlevleri üstlenir?", "a": "AutoUpgrade aracı veritabanı yükseltme süreçlerinin otomasyonunu, yükseltme öncesi kontrollerin (pre-checks) çalıştırılmasını ve yükseltme aşamalarının yönetilmesini sağlar [1]. Yükseltme boru hattını uçtan uca otomatik yöneterek manuel hata riskini en aza indirir [1]. Resmî dokümantasyon bu AutoUpgrade aracını doğrudan Oracle Database 19c sürüm yükseltmeleri için belgelendirmektedir [1].", "sources": [{"title": "Oracle Database Database Upgrade Guide, 19c", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/upgrd/"}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Oracle veritabanı yama stratejisinde Release Update (RU) nedir ve veritabanı sürüm numarasına nasıl etki eder?", "a": "Release Update (RU), güvenlik açıklarını, yüksek değerli hata düzeltmelerini ve kritik kararlılık geliştirmelerini içeren üç aylık birikimli bir yamadır [1]. RU uygulaması veritabanını yeni bir ikincil sürüme taşır ve ikincil sürüm numarasını artırır (örneğin 19.11 değerinden 19.12 değerine) [1]. Performans değişikliklerini doğrulamak amacıyla ana güncelleme döngülerinde üretim dışı ortamlarda (DEV ve TEST) uygulanması önerilir [1]. Kaynaklar bu RU revizyon örneklerini Oracle Database 19c ve IFS Applications 10/9 ortamları bağlamında sunmaktadır [1].", "sources": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Release Update Revision (RUR) yamalarının temel kullanım amacı nedir ve Release Update (RU) paketlerinden farkı nasıl tanımlanır?", "a": "Release Update Revision (RUR), yeni işlevsel hata düzeltmesi eklemeden mevcut bir RU için kritik güvenlik ve regresyon düzeltmeleri sunarak RU ömrünü uzatır [1]. RUR uygulaması revizyon rakamını artırır (örneğin 19.11.0 değerinden 19.11.1 değerine) ve her RU için en fazla iki revizyon yayınlanır [1]. Temel yürütme davranışını kilitlerken güvenlik güncellemeleri gerektiren üretim (PROD) ortamlarında tercih edilir [1]. Kaynaklar bu RUR tanımını Oracle Database 19c ve IFS Applications ortamları için vermektedir [1].", "sources": [{"title": "Release Update (RU) & Release Update Revision (RUR) Lifecycle", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "Veritabanı yama uygulaması öncesinde OPatch yardımcı programı ile hangi ön doğrulamalar ve kontroller yapılır?", "a": "Yama kurulumu çalıştırılmadan önce OPatch yardımcı programı Oracle Patch Readme dosyasında belirtilen minimum sürüme güncellenmelidir [1]. Oracle Home ($ORACLE_HOME) üzerinde çakışma tespiti (conflict detection) yapılarak kısmi yama uygulamaları engellenir ve veritabanı servisleri durdurulmadan önce tüm sistem önkoşulları doğrulanır [1]. Bu ön kontroller yazılım bozulmalarını ve beklenmeyen kesintileri önler [1]. Kaynaklar bu OPatch doğrulama adımları için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Patch Application Execution", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "İki aşamalı yama boru hattında birinci aşama olan ikili dosya yamalama (opatch apply) süreci nasıl yürütülür?", "a": "Birinci aşamada veritabanı servisleri tamamen durdurulmuş durumdayken opatch apply komutu çalıştırılır [1]. Bu komut $ORACLE_HOME dizinindeki yürütülebilir ikili dosyaları, kütüphaneleri ve başlık dosyalarını doğrudan günceller [1]. İkili dosya güncellemesi tamamlanmadan veritabanı servisleri yeniden başlatılmaz [1]. Kaynaklar ikili dosya yamalama süreci için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "Patch Application Execution", "url": ""}]}, {"chapter": 3, "title": "Bölüm 3: Sürüm Yaşam Döngüsü, Yama Yönetimi ve Veritabanı Yükseltme", "q": "İki aşamalı yama boru hattında ikinci aşama olan datapatch otomasyonu ne zaman ve hangi veritabanı katmanlarında çalıştırılır?", "a": "İkili dosya güncellemesi tamamlanıp veritabanı servisleri yeniden açıldıktan sonra datapatch otomasyonu çalıştırılır [1]. Datapatch aracı CDB$ROOT kök konteynerinde ve tüm Pluggable Database (PDB) yapılarında SQL metadatasını, veri sözlüğü nesnelerini ve PL/SQL paketlerini otomatik olarak günceller [1]. Bu sayede SQL düzeyindeki yama adımları tüm konteynerlere uygulanmış olur [1]. Kaynaklar multitenant veritabanlarında datapatch kullanımı için özel bir sürüm kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Patch Application Execution", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "ASM Fine-Grained Striping mekanizması Allocation Unit birimlerini nasıl böler ve hangi veritabanı varlıklarında gecikmeyi düşürür?", "a": "Fine-Grained Striping, Allocation Unit birimlerini tüm diskler üzerine dağıtılan 128 KB boyutundaki daha küçük şerit kümelerine böler [1]. Online Redo Logs (ORLs), Control Files ve Flashback Logs gibi düşük gecikme gerektiren küçük boyutlu yazma operasyonlarında I/O süresini optimize etmek için kullanılır [1]. Bu sayede eşzamanlı küçük yazma operasyonlarındaki gecikmeler en aza indirilir [1]. Kaynaklar Fine-Grained Striping mekanizması için belirli bir veritabanı sürümü koymamaktadır [1].", "sources": [{"title": "ASM Striping & Redundancy for OLTP", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "ASM disk gruplarının toplam kapasitesini, boş alanını ve kullanım yüzdesini sorgulamak için veritabanı yöneticileri hangi SQL sorgusunu çalıştırır?", "a": "Veritabanı yöneticileri ASM örneğine (+ASM) bağlanarak v$asm_diskgroup görünümünü sorgular [1]. Bu görünüm üzerinden total_mb ve free_mb sütunları kullanılarak disk grubunun toplam boyutu, boş alanı ve yüzde kullanım oranı hesaplanır [1]. Bu sorgu sayesinde DATA ve RECO disk gruplarının doluluk durumları anlık olarak izlenir [2, 1]. Kaynaklar bu görünüm sorgusu için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Tablespace & ASM Disk Space Thresholds", "url": ""}, {"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "IFS Cloud ortamlarında tablo bölümleme (table partitioning) uygulaması kaynaklarda nasıl açıklanmaktadır?", "a": "Resmî IFS Cloud dokümantasyonunda Oracle Partitioning seçeneğinin IFS Cloud ile kullanımı desteklenen ('Y') bir özellik olarak belirtilmektedir [1]. Tablo bölümleme ile küresel ve yerel indeks bölümlerinin IFS Applications 9 & 10 üzerinde test edildiği ve doğrulandığı ifade edilmiştir [1]. Ancak kaynaklar yüksek hacimli işlem tablolarında bölümleme stratejilerinin adım adım uygulanmasına dair daha ayrıntılı kod veya komut bilgisi vermemektedir [1]. Kaynakların kapsamadığı bu uygulama ayrıntıları kaynaklarda yer almadığı için açıkça belirtilmiştir [1].", "sources": [{"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-010-planning-installation-010-storage-tier-considerations-010-oracle-db-19c-Oracle-19c-Enterprise-Edition-19c-options-and-feat.pdf", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Kurtarma operasyonları için ayrılan RECO disk grubunun rolü nedir ve veri dosyalarından izole edilmesi ne sağlar?", "a": "RECO (veya FRA) disk grubu; arşiv logları, RMAN yedek kümeleri, kontrol dosyası kopyaları, Flashback logları ve online redo logların çoklanan kopyalarını depolayan adanmış kurtarma alanıdır [1]. Kurtarma dosyalarının DATA grubundan izole edilmesi, ağır yedekleme veya arşivleme işlemlerinin aktif veritabanı işlemleriyle disk bant genişliği için yarışmasını engeller [1]. Bu sayede aktif işlem performansı aksamadan korunur [1]. Kaynaklar bu kurtarma alanı yapısı için özel bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Oracle ASM depolama yapısında External, Normal ve High Redundancy modelleri veriyi nasıl korur?", "a": "External Redundancy modelinde ASM seviyesinde aynalama yapılmaz ve veri koruması donanım RAID veya SAN mimarisine bırakılır [1, 2]. Normal Redundancy en az iki Failure Group arasında 2 yönlü aynalama sağlarken, High Redundancy en az üç Failure Group arasında 3 yönlü aynalama uygular [1, 2]. Yüksek erişilebilirlik gerektiren kritik IFS kurumsal kurulumlarında High Redundancy tercih edilir [1, 2]. Kaynaklar bu yedeklilik seviyeleri için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1, 2].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}, {"title": "ASM Striping & Redundancy for OLTP", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Oracle ASM şeritlendirme mimarisinde Coarse-Grained Striping hangi dosya türleri ve I/O erişim kalıpları için kullanılır?", "a": "Coarse-Grained Striping, Allocation Unit (AU) boyutunun tamamını (genellikle 1 MB ila 4 MB) kullanarak veriyi diskler üzerine dağıtır [1]. Veritabanı veri dosyaları, indeks tablespace'leri, geçici dosyalar ve RMAN yedek kümeleri gibi büyük ve sıralı I/O gerektiren veri yapıları için tasarlanmıştır [1]. Bu şeritlendirme modeli büyük veri bloklarının sıralı okunmasını optimize eder [1]. Kaynaklar Coarse-Grained Striping kullanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "ASM Striping & Redundancy for OLTP", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Oracle Automatic Storage Management (ASM) mimarisinde DATA disk grubunun birincil işlevi nedir ve hangi dosya türlerini barındırır?", "a": "DATA disk grubu, aktif veri dosyalarını, indeks tablespace'lerini, SYSTEM ve SYSAUX tablespace'lerini, geçici dosyaları ve online redo log gruplarını barındıran birincil operasyonel depolama alanıdır [1]. IFS Applications (IFS Cloud ve IFS Applications 10/9) orta katman işlemlerini yürütmek için bu grupta yüksek okuma ve yazma IOPS performansına öncelik verilir [1]. Bu depolama yapısı aktif veritabanı operasyonlarının yüksek başarım ile yürütülmesini sağlar [1]. Kaynaklar bu disk grubu tanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Disk Group Architecture (DATA & RECO)", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Oracle Enterprise Manager (OEM) üzerinden tanımlanan yüzde 85 uyarı (warning) ve yüzde 95 kritik (critical) alan eşiklerinin operasyonel amacı nedir?", "a": "%85 uyarı eşiği, veritabanı yöneticilerine veri dosyası büyümesini inceleme ve rutin bakım pencerelerinde alan genişletme planlama imkanı tanır [1]. %95 kritik eşiği ise yetersiz alan nedeniyle oluşabilecek kesintileri ve veritabanı duraklamalarını önlemek için acil idari müdahale gerektiğini gösterir [1]. Bu iki kademeli uyarı yapısı ERP operasyonlarının kararlılığını korur [1]. Kaynaklar bu depolama eşik değerleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Tablespace & ASM Disk Space Thresholds", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Veritabanı seviyesinde tablespace alan kullanımı uyarı eşikleri programatik olarak hangi PL/SQL paketi ve yordamı ile tanımlanır?", "a": "Tablespace alan kullanımı uyarı eşikleri DBMS_SERVER_ALERT paketi ve SET_THRESHOLD yordamı çalıştırılarak programatik olarak tanımlanır [1]. warning_value parametresi '85', critical_value parametresi '95' ve metric_id parametresi TABLESPACE_SPACE_USAGE olarak ayarlanır [1]. Yapılandırılan bu eşik ayarları DBA_THRESHOLDS veri sözlüğü görünümü sorgulanarak doğrulanır [1]. Kaynaklar bu PL/SQL paketi ve görünüm kullanımı için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Tablespace & ASM Disk Space Thresholds", "url": ""}]}, {"chapter": 4, "title": "Bölüm 4: Depolama Mimarisi, ASM ve Kapasite Yönetimi", "q": "Veritabanı yöneticileri bir veritabanı dosyasının ASM şeritlendirme durumunu ve disk grubu özelliklerini hangi dinamik görünümlerden sorgular?", "a": "Veritabanı yöneticileri ASM örneğine (+ASM) bağlanarak V\\(ASM_FILE ve V\\)ASM_ALIAS görünümlerinden dosyaların fine veya coarse şeritlendirme durumlarını denetler [1]. Disk grubu boş alanı, Allocation Unit boyutları ve yedeklilik seviyeleri ise V$ASM_DISKGROUP görünümü üzerinden sorgulanır [2]. Bu görünümler depolama katmanının anlık durumunu inceleme imkanı verir [2, 1]. Resmî Oracle kılavuzu bu ASM yönetimi araçlarını Release 19c için belgelemektedir [3].", "sources": [{"title": "ASM Striping & Redundancy for OLTP", "url": ""}, {"title": "Disk Group Architecture (DATA & RECO)", "url": ""}, {"title": "Oracle Automatic Storage Management Administrator's Guide", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/ostmg/"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Fast Application Notification (FAN) ve Oracle Notification Service (ONS) altyapısı istemci bağlantı havuzlarına nasıl bir fayda sağlar?", "a": "Fast Application Notification (FAN), veritabanı düğüm veya servis durum değişikliklerini (UP ve DOWN olayları) ve yük dengeleme metriklerini gerçek zamanlı yayınlar [1]. Oracle Database 12c Release 2 (12.2) ve sonraki sürümlerde tüm istemciler FAN olaylarını almak için Oracle Notification Service (ONS) kullanır [1]. Entegre bağlantı havuzları ONS üzerinden gelen FAN olaylarına abone olarak kesintiye uğrayan ölü bağlantıları derhal temizler ve TCP/IP zaman aşımı askıda kalmalarını önler [1]. Kaynaklar ONS kullanımının tüm istemciler için standart hale gelmesini Oracle Database 12c Release 2 (12.2) sürümü olarak belirtmektedir [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Global Resource Directory (GRD) yapısının Oracle RAC bellek yönetimi ve tampon bellek tutarlılığındaki rolü nedir?", "a": "Global Resource Directory (GRD), kümedeki tüm düğümler genelinde önbelleğe alınmış her bir veri bloğunun durumunu, konumunu ve kilit bilgisini anlık olarak takip eder [1, 2]. Global Cache Service (GCS) ve Global Enqueue Service (GES) süreçleri tampon bellek bloklarını ve kilitleri GRD üzerinde koordine ederek kirli okumaları (dirty reads) önler [1, 2]. GRD içeriği tüm aktif örnekler arasında dağıtılır ve bellek kullanımı toplam SGA alanının yaklaşık yüzde 10'una denk gelir [2]. Kaynaklar GRD yapısının bellek oranı ve işlevleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1, 2].", "sources": [{"title": "Active-Active Node Clustering", "url": ""}, {"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "High Availability IP (HAIP) teknolojisi Oracle RAC özel Interconnect ağında nasıl bir koruma ve yedeklilik sağlar?", "a": "High Availability IP (HAIP), Oracle Grid Infrastructure 11g Release 2 (11.2) ve sonraki sürümlerde sunulan ve birden fazla fiziksel ağ kartını (NIC) yedekli olarak kullanan bir teknolojidir [1, 2]. HAIP mimarisi, fiziksel bir Interconnect ağ kartı arızalandığında veya ağ hattı koptuğunda kesintisiz çalışma ve yüksek veri akışı sağlar [1, 2]. Bu sayede Cache Fusion bloğu transferleri ağ kartı arızalarından etkilenmeden devam eder [1]. Kaynaklar bu HAIP özelliğini Oracle Grid Infrastructure 11g Release 2 (11.2) ve sonrası sürümlere ait olarak belirtmektedir [1, 2].", "sources": [{"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": ""}, {"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle Clusterware mimarisinde Cluster Ready Services (CRS/CRSD) hangi küme kaynaklarını yönetir ve arıza durumunda nasıl tepki verir?", "a": "Cluster Ready Services (CRS/CRSD) ana süreci; VIP adresleri, SCAN dinleyicileri, veritabanı örnekleri ve kullanıcı tanımlı servisler gibi yüksek erişilebilirlik kaynaklarını yönetir [1]. Yönettiği bu kaynakların konfigürasyon bilgilerini Oracle Cluster Registry (OCR) deposunda saklar [2]. Bir kaynak arızalandığında CRS bu kaynağı otomatik olarak yeniden başlatır veya sağlıklı düğümlere taşır [1, 2]. Kaynaklar CRS bileşeninin bu kaynak yönetim işlevleri için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": ""}, {"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle Grid Infrastructure yazılım yığını bünyesinde yer alan Cluster Synchronization Services (CSS) bileşeninin temel işlevi nedir?", "a": "Cluster Synchronization Services (CSS), küme düğüm üyeliğini takip eder ve düğümlerin yanıt verme durumlarını sürekli denetler [1]. Bir düğüm arızalandığında veya kümenin geri kalanıyla iletişimi koptuğunda, CSS bölünmüş beyin (split-brain) senaryolarını önlemek için ilgili düğümün kümeden tahliye edilmesini (eviction) sağlar [1]. Bu sayede veritabanı tutarlılığı ve küme bütünlüğü korunmuş olur [1]. Kaynaklar CSS bileşeninin bu temel görevi için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": ""}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle RAC aktif-aktif kümeleme mimarisinde her bir veritabanı örneği (instance) bellek ve süreç bazında nasıl çalışır?", "a": "Oracle RAC aktif-aktif kümeleme mimarisinde her düğüm kendi System Global Area (SGA) bellek yapılarını ve arka plan süreçlerini çalıştırır [1]. Aktif-pasif yapılardan farklı olarak kümedeki tüm düğümler eşzamanlı olarak aktif bağlantıları kabul eder ve IFS Applications orta katman bağlantı havuzlarından gelen işlemleri yürütür [1, 2]. Tüm örnekler paylaşılan veritabanı dosyalarına Oracle ASM disk grupları üzerinden erişir [1]. Kaynaklar bu aktif-aktif mimari tanımları için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Active-Active Node Clustering", "url": ""}, {"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": ""}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle RAC mimarisinde özel Interconnect ağı ve Cache Fusion mekanizması veritabanı blok transferini nasıl gerçekleştirir?", "a": "Özel Interconnect ağı, küme düğümlerini doğrudan birbirine bağlayan adanmış ve yüksek hızlı bir ağ altyapısıdır [1, 2]. Cache Fusion mekanizması, bir veritabanı örneğinin bellek önbelleğinde bulunan veri bloklarını diske yazmaya gerek kalmadan özel Interconnect ağı üzerinden diğer örneğin önbelleğine doğrudan aktarır [1, 2]. Bu disksiz bellek aktarımı sayesinde I/O gecikmeleri en aza indirilir ve işlem performansı artırılır [1, 2]. Kaynaklar bu Interconnect ve Cache Fusion prensipleri için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "Active-Active Node Clustering", "url": ""}, {"title": "RAC Grid Infrastructure & Interconnect Configuration", "url": ""}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle RAC ortamında run-time connection load balancing ve Load Balancing Advisory metrikleri nasıl çalışır?", "a": "Load Balancing Advisory, veritabanı örneklerinin sunduğu anlık servis kalitesini değerlendirerek performans tavsiyeleri üretir ve bu metrikleri ONS üzerinden yayınlar [1]. Entegre istemci bağlantı havuzları (UCP, OCI session pool, ODP.NET) bu tavsiyeleri alarak gelen iş isteklerini en iyi servis süresini sunan örneklere dinamik olarak yönlendirir [1]. Bu çalışma için servis üzerinde runtime load balancing goal (-rlbgoal SERVICE_TIME veya THROUGHPUT) ve connection load balancing goal (-clbgoal SHORT) yapılandırılmalıdır [1]. Kaynaklar bu yük dengeleme tavsiyesi parametreleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Oracle RAC veritabanı yöneticisi özel Interconnect ağının aktif kullanımını ve arayüz ayarlarını hangi SQL görünümlerinden denetler?", "a": "Veritabanı yöneticileri özel Interconnect ağ yapılandırmasını ve aktif kullanılan ağ arayüzlerini V\\(CLUSTER_INTERCONNECTS, V\\)CONFIGURED_INTERCONNECTS veya küme genelinde GV$CLUSTER_INTERCONNECTS görünümlerini sorgulayarak doğrular [1]. Bu görünümler IP adreslerini, ağ arabirim adlarını ve kaynağın Oracle Cluster Registry (OCR) olduğunu görüntüler [1]. Böylece Cache Fusion trafiğinin doğru özel ağ üzerinden aktığı teyit edilir [2, 1]. Kaynaklar bu performans görünümleri için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}, {"title": "Active-Active Node Clustering", "url": ""}]}, {"chapter": 5, "title": "Bölüm 5: RAC ve Grid Infrastructure Kümeleme Mimarisi", "q": "Single Client Access Name (SCAN) ve SCAN dinleyicileri istemci bağlantılarını veritabanı düğümlerine nasıl yönlendirir?", "a": "Single Client Access Name (SCAN), küme içinde üç ayrı VIP adresine çözümlenen ve küme yaşam döngüsü boyunca değişmeyen tekil bir ağ adıdır [1]. İistemci SCAN adresine bağlandığında, SCAN dinleyicisi ilgili servisi barındıran en uygun veritabanı örneğini belirler ve istemciyi o düğümdeki yerel dinleyiciye (local listener) yönlendirir [1]. Oracle Database 12c Release 2 (12.2) sürümünde SCAN dinleyicisine HTTP protokolü desteği eklenerek HTTP istemcilerinin küme düğümlerine yönlendirilmesi sağlanmıştır [1]. Kaynaklar SCAN temel yönlendirme mekanizmasını açıklar, HTTP desteğini ise Oracle Database 12c Release 2 (12.2) sürümüne tarihler [1].", "sources": [{"title": "Real Application Clusters Administration and Deployment Guide - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/racad/real-application-clusters-administration-and-deployment-guide.pdf"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Active Data Guard ortamında birincil ve standby veritabanı rollerini ve Real-Time Apply durumunu doğrulamak için hangi veri sözlüğü görünümleri sorgulanır?", "a": "Veritabanı rolü ve açık olma modu v$database görünümündeki database_role ve open_mode sütunlarından doğrulanır. Kurtarma sürecinin aktifliği v$managed_standby görünümündeki MRP0 süreci ve status sütunundan denetlenir. Replikasyon gecikme süreleri ise v$dataguard_stats görünümündeki apply lag metriği sorgulanarak kontrol edilir. Kaynaklar bu doğrulama görünümleri için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Data Guard Broker (dgmgrl) etkinleştirilirken karşılaşılan ORA-16698 hatası ne anlama gelir ve nasıl çözülür?", "a": "ORA-16698 hatası, manuel LOG_ARCHIVE_DEST_n parametresinde SERVICE özniteliğinin tanımlı olmasından kaynaklanır. Hatayı çözmek için manuel arşiv hedefleri ALTER SYSTEM SET LOG_ARCHIVE_DEST_2='' SCOPE=BOTH SID='*'; komutuyla temizlenir. Ardından Data Guard Broker, ALTER SYSTEM SET DG_BROKER_START=TRUE SCOPE=BOTH SID='*'; komutuyla başlatılır. Mimari çalışma notları bu komutları ve hatanın çözümünü Oracle Database 19c sürümü için detaylandırmaktadır.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Data Guard Real-Time Redo Apply mekanizması geleneksel arşiv log uygulama yönteminden nasıl ayrılır ve RPO/RTO hedeflerine nasıl katkı sağlar?", "a": "Birincil veritabanındaki Log Network Server (LNS) süreci redo verisini iletir ve standby tarafındaki Remote File Server (RFS) süreci bu veriyi doğrudan aktif SRL dosyalarına yazar. Managed Recovery Process (MRP0), redo verilerini SRL dosyalarından bellek ve diske anında uygulayarak geleneksel arşiv log biriktirme gecikmesini ortadan kaldırır. Bu Real-Time Apply yapısı, veri kaybını önleyerek RPO = 0 ve hızlı failover ile RTO < 5 dakika hedeflerine ulaşılmasını sağlar. Kaynaklar bu mekanizmayı Oracle Database 19c ve IFS Applications iş yükleri için açıklamaktadır.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Data Guard rol geçişlerinde planlı switchover operasyonu ile acil durum failover operasyonu arasındaki temel farklar nelerdir?", "a": "Planlı switchover, birincil ve standby veritabanları arasında iki yönlü, sıfır veri kayıpsız (RPO = 0) ve veritabanlarının yeniden oluşturulmasını gerektirmeyen rol değişimidir. Acil durum failover ise birincil veritabanının çökmesi durumunda standby veritabanını birincil role yükselten tek yönlü bir acil durum işlemidir. Maximum Performance modunda yapılan failover işlemlerinde unapplied redo nedeniyle veri kaybı (RPO > 0) yaşanabilir. Kaynaklar bu rol değişim tanımları için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Fiziksel bir standby veritabanını Active Data Guard ile salt okunur modda açmak için sırasıyla hangi SQL komutları çalıştırılır?", "a": "İlk olarak ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL; komutu ile mevcut yönetilen kurtarma durdurulur. Ardından ALTER DATABASE OPEN; komutu ile veritabanı salt okunur modda açılır. Son olarak ALTER DATABASE RECOVER MANAGED STANDBY DATABASE USING CURRENT LOGFILE DISCONNECT; komutu çalıştırılarak Real-Time Apply ile yönetilen kurtarma yeniden başlatılır. Kaynaklar bu SQL komut dizilimi için spesifik bir veritabanı sürümü belirtmemektedir.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Oracle Active Data Guard fiziksel standby veritabanının salt okunur (Read-Only) modda açılması veritabanı performansına nasıl katkı sağlar?", "a": "Active Data Guard, fiziksel standby veritabanının arka planda MRP0 süreci ile Real-Time Apply yaparken aynı anda salt okunur (READ ONLY) modda açılmasına imkan tanır. Ağır analitik sorgular, finansal raporlar ve harici BI entegrasyonları standby veritabanına yönlendirilir (query offloading). Bu sayede birincil veritabanındaki CPU ve I/O kaynakları korunarak çekirdek OLTP işlemlerinin yanıt süreleri optimize edilir. Kaynaklar bu Active Data Guard mimarisini Oracle Database 19c ve IFS Applications iş yükleri bağlamında sunmaktadır.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Oracle Data Guard Fast-Start Failover (FSFO) altyapısının temel çalışma prensibi nedir ve hangi teknik önkoşula dayanır?", "a": "Fast-Start Failover (FSFO), bağımsız bir konumda çalışan Observer süreci aracılığıyla birincil veritabanının çökmesi durumunda standby veritabanına otomatik failover gerçekleştiren mekanizmadır. Observer birincil veritabanına ulaşamadığında ve belirlenen FastStartFailoverThreshold süresi dolduğunda otomatik failover başlatır. FSFO mekanizmasının çalışabilmesi için veritabanında Flashback Database özelliğinin aktif olması kesinlikle zorunludur. Kaynaklar FSFO ve Flashback zorunluluğu için spesifik bir veritabanı sürümü kısıtlaması belirtmemektedir.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Oracle Data Guard altyapısında Standby Redo Logs (SRLs) yapılandırmasının temel kuralları nelerdir?", "a": "Standby Redo Log (SRL) dosyaları, rol değişimlerinde veri alabilmek için hem birincil hem de standby veritabanlarında oluşturulmalıdır. SRL dosya boyutları, birincil veritabanının Online Redo Log (ORL) dosyalarıyla birebir aynı boyutta ayarlanmalıdır. Her bir redo kanalı (thread) için gerekli minimum SRL grup sayısı formülü (Thread Başına ORL Grubu Sayısı) + 1 şeklinde hesaplanır. Kaynaklar bu SRL yapılandırma kuralları için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Oracle Database@Azure bulut altyapısında Data Guard senkronizasyonu için önerilen ağ peering yöntemi ve güvenlik yapılandırması nedir?", "a": "Oracle Database@Azure üzerinde birincil ve standby Exadata sanal makine kümeleri ayrı Virtual Cloud Network (VCN) yapılarına dağıtılır. Redo taşıma bant genişliğini artırmak ve taşıma gecikmesini düşürmek için OCI VCN Peering (Local Peering Gateway / Dynamic Routing Gateway) kullanılması önerilir. TDE şifreleme anahtarları OCI Private Vault içinde tutulur ve bölgeler arasında replike edilir. Resmî dokümantasyon bu bulut ağ mimarisini Oracle Database@Azure ortamına özgü olarak sunmaktadır.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 6, "title": "Bölüm 6: Data Guard, MAA Standartları ve Felaket Kurtarma Operasyonları", "q": "Oracle Maximum Availability Architecture (MAA) bünyesinde tanımlanan Bronze, Silver, Gold ve Platinum katmanları arasındaki temel farklar nelerdir?", "a": "Bronze katmanı tek veritabanı örneği ve depolama yedeklemesi sunarken, Silver katmanı Oracle RAC ile yerel yüksek erişilebilirlik sağlar. Gold katmanı yerel RAC kümelemesini uzaktaki Oracle Data Guard veya Active Data Guard (ADG) fiziksel standby veritabanı ile birleştirerek RPO = 0 ve RTO < 1 dakika hedeflerini yakalar. Platinum katmanı ise Gold katmanına Oracle GoldenGate aktif-aktif replikasyonu ve Edition-Based Redefinition ekleyerek sıfır bakım penceresi etkisi sunar. Mimari notlar Gold mimarisini Oracle Database 19c bağlamında sunarken, resmî Oracle dokümantasyonu MAA Platinum Seçenek 1 mimarisi için Oracle AI Database 26ai veya üzerini şart koşmaktadır.", "sources": [{"title": "Automated Switchover & Failover Runbooks", "url": ""}, {"title": "Gold & Platinum MAA Standards Implementation", "url": ""}, {"title": "RPO & RTO High Availability Optimization", "url": ""}, {"title": "Real-Time Replica Synchronization", "url": ""}, {"title": "Read-Only Query & Reporting Offloading", "url": ""}, {"title": "CPU Utilization & Data Guard Lag Thresholds", "url": ""}, {"title": "Architectural Blueprint for Oracle 19c Maximum Availability Architecture in Enterprise ERP Workloads", "url": ""}, {"title": "Maximum Availability Architecture(MAA): - Oracle E-Business Suite Release 12", "url": "https://www.oracle.com/technetwork/articles/oem/298391-132409.pdf"}, {"title": "High Availability Best Practices and Overview", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/"}, {"title": "Oracle Maximum Availability Architecture for Oracle Database@Azure", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/haovw/oracle-maximum-availability-architecture-oracle-databaseazure.html"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Application Continuity kullanımı sırasında koruma seviyesi ve performans metrikleri hangi veritabanı görünümlerinden izlenir?", "a": "Application Continuity koruma seviyesi ve istek sınırlarına ait istatistikler veritabanı içinde V\\(SESSTAT ve V\\)SYSSTAT görünümleri üzerinden izlenebilir [1]. Oracle Database 19c sürümünün sonraki versiyonlarında bu metrikler ek olarak V$SERVICE_STATS görünümünde de sunulur [1]. Ayrıca AWR raporları bu koruma verilerini geçmişe dönük olarak saklar [1]. Kaynaklar V$SERVICE_STATS üzerinden izleme yapılmasını Oracle Database 19c sürümüne tarihlendirmektedir [1].", "sources": [{"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Application Continuity mekanizmasının kesinti sonrasında işlemleri güvenle yeniden çalıştırabilmesi için hangi veritabanı bileşeni zorunludur ve bu bileşen nasıl çalışır?", "a": "Application Continuity özelliğinin kullanılabilmesi için Transaction Guard bileşeninin kullanılması zorunludur [1]. Transaction Guard, yürütülen işlemlere Mantıksal İşlem Kimliği (LTXID) atayarak kesinti sonrasında işlemin taahhüt durumunu (commit outcome) kesin olarak doğrular. Bu doğrulama sayesinde tamamlanan işlemlerin mükerrer çalıştırılması engellenir ve güvenli kurtarma sağlanır [1, 2]. Kaynaklar Transaction Guard için spesifik bir sürüm kısıtlaması belirtmemektedir [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Application Continuity mimarisinde tekrarlanmaması gereken harici yan etkileri (side effects) bulunan işlemler için nasıl bir yöntem izlenir?", "a": "E-posta gönderimi (UTL_SMTP) veya HTTP çağrıları (UTL_HTTP) gibi geri alınamayan harici yan etkileri bulunan işlemlerde, ReplayableConnection arabirimindeki disableReplay metodu çağrılarak ilgili istek için replay devre dışı bırakılır [1]. Transparent Application Continuity (TAC) modunda ise sistem çalışma zamanında yan etkileri otomatik olarak tespit eder ve replay yakalamasını durdurur [2]. Böylece kesinti kurtarmasında mükerrer harici eylemler önlenir [2, 1]. Kaynaklar disableReplay API kullanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "IFS Applications orta katman altyapısında veritabanı kesintilerini algılamak için ONS ve FCF nasıl yapılandırılır?", "a": "Enterprise ortamlarda çalışan IFS Applications altyapısı, kesintileri anında algılamak için Oracle Notification Service (ONS) ve Fast Connection Failover (FCF) mekanizmasını kullanır [1, 2]. ONS, veritabanı ve servis durum değişikliklerini (FAN olayları) varsayılan 6200 portu üzerinden yayınlar [1]. JDBC Universal Connection Pool (UCP) üzerinde fastConnectionFailoverEnabled=true ayarlanarak FCF etkinleştirilir ve kesintiye uğrayan ölü bağlantılar derhal temizlenir [2, 1]. Kaynaklar IFS mid-tier test senaryolarında bu yapılandırma için spesifik bir veritabanı sürümü belirtmemektedir [2].", "sources": [{"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}, {"title": "IFS Mid-Tier Re-connection Logic Testing", "url": ""}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "IFS Applications orta katman sunucularında Data Guard switchover sonrası yük devretme doğrulaması hangi adımlarla test edilir?", "a": "İlk olarak IFS orta katman veri kaynağı URL'si SCAN dinleyici sözdizimi ve ONS düğümleriyle yapılandırılır [1]. Ardından Data Guard Broker (DGMGRL) arayüzünden SWITCHOVER TO komutu çalıştırılarak birincil veritabanı rolü standby veritabanına devredilir [1]. IFS uygulama sunucusu günlük dosyaları (log files) incelenerek ONS FCF olaylarının alındığı, eski bağlantıların temizlendiği ve SQL sorgularının yeni birincil veritabanında kesintisiz çalıştığı doğrulanır [1]. Kaynaklar bu test adımlarını IFS mid-tier re-connection logic test dokümanı kapsamında sunmaktadır [1].", "sources": [{"title": "IFS Mid-Tier Re-connection Logic Testing", "url": ""}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Oracle Database 19c sürümünde veritabanı servisinde -failovertype AUTO tanımlandığında failover_restore parametresi nasıl davranır?", "a": "Oracle Database 19c sürümünde veritabanı servisine -failovertype AUTO atandığında, -failover_restore parametresinin değeri otomatik olarak AUTO yapılır [1]. Bu ayar, kesinti sonrasında yeni veritabanı örneğinde oturum yeniden kurulurken NLS ayarlarını, zaman dilimlerini ve oturum durumlarını otomatik olarak geri yükler [1]. Bu sayede uygulama katmanı durum kaybı yaşamadan çalışmaya devam eder [1]. Kaynaklar bu otomatik atanma davranışını Oracle Database 19c sürümüne özgü olarak sunmaktadır [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Oracle veritabanı altyapısında Transparent Application Continuity (TAC) ile manuel Application Continuity (AC) arasındaki temel fark nedir ve TAC hangi sürümde tanıtılmıştır?", "a": "Transparent Application Continuity (TAC), uygulama kodunda değişiklik veya istek sınırı (request boundary) tanımlaması gerektirmeden oturum ve işlem durumunu şeffaf bir şekilde izler [1, 2]. Manuel Application Continuity (AC) ise uygulama tarafında beginRequest ve endRequest API çağrıları ile istek sınırlarının açıkça bildirilmesini gerektirir [1]. TAC özelliği Oracle Database 18c sürümünde tanıtılmış ve Oracle Database 19c sürümünde desteklenmiştir; manuel AC ise Oracle Database 12c Release 1 (12.1) sürümünden itibaren mevcuttur [1, 2].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Oracle veritabanında planlı bakım öncesinde sunucu tarafı oturum boşaltma (server-side session draining) süreci nasıl işler?", "a": "Planlı bakım başlatılmadan önce veritabanı servisleri üzerinden FAN planned DOWN olayları yayınlanır [1]. FAN uyumlu bağlantı havuzları boşta duran oturumları kapatır ve aktif oturumları belirlenen drain_timeout süresi içinde istek sınırlarında kesintisiz olarak boşaltır. İşlemler drain_timeout süresi içinde tamamlanamazsa stopoption (IMMEDIATE) devreye girerek kalan oturumları sonlandırır [1]. Kaynaklar veritabanı seviyesinde sunucu tarafı oturum boşaltma özelliğinin Oracle Database 18c sürümünde getirildiğini belirtmektedir [1].", "sources": [{"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "Transparent Application Continuity (TAC) modunda srvctl aracı ile veritabanı servisi yapılandırılırken hangi parametreler ayarlanır?", "a": "srvctl aracı ile veritabanı servisi oluşturulurken -failovertype AUTO parametresi ayarlanarak Transparent Application Continuity (TAC) etkinleştirilir [1]. Servis üzerinde -commit_outcome TRUE parametresi tanımlanarak Transaction Guard altyapısı devreye sokulur [1]. Ayrıca yeniden başlatma gecikmelerini ve deneme sayılarını yönetmek için -failoverretry 30 ve -failoverdelay 10 parametreleri yapılandırılır [1]. Kaynaklar -failovertype AUTO parametresinin kullanımını Oracle Database 18c ve 19c sürümlerine bağlamaktadır [1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}]}, {"chapter": 7, "title": "Bölüm 7: Uygulama Sürekliliği ve Dayanıklılık Mimarisi", "q": "İstemci JDBC ve TNS bağlantı dizelerinde kesintisiz yük devretme sağlamak için hangi bağlantı parametreleri tanımlanmalıdır?", "a": "İstemci bağlantı tanımlarında CONNECT_TIMEOUT, RETRY_COUNT, RETRY_DELAY ve FAILOVER=ON parametrelerinin yer alması zorunludur. Oracle Database Release 12.1.0.2 ve üzeri sürümlerde ek olarak TRANSPORT_CONNECT_TIMEOUT parametresi tanımlanır [1, 2]. Ayrıca SCAN VIP adreslerini içeren bir ADDRESS_LIST yapısı tanımlanarak bağlantı isteklerinin aktif küme düğümlerine yönlendirilmesi sağlanır [3, 1]. Bu parametreler sunucu kesintilerinde istemcinin zaman aşımı askıda kalmasını önler [2, 1].", "sources": [{"title": "28 Application Continuity for Java - Database - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/jjdbc/application-continuity.html"}, {"title": "Application Continuity for the Oracle Database", "url": "https://www.oracle.com/docs/tech/database/applicationcontinuityformaa.pdf"}, {"title": "IFS Mid-Tier Re-connection Logic Testing", "url": ""}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "ASH sorgularında db file sequential read ve db file scattered read bekleme olayları hangi I/O operasyonlarını ve sorunları temsil eder?", "a": "db file sequential read bekleme olayı tek blok indeks okumalarını temsil eder ve yüksek bekleme süreleri gösterdiğinde indekslenmemiş sorgulara veya parçalanmış B-Tree indekslerine işaret eder [1, 2]. db file scattered read bekleme olayı ise çoklu blok tam tablo taramalarını (Full Table Scan) ve toplu iş süreçlerindeki okuma operasyonlarını temsil eder [1, 2]. Her iki bekleme olayı da diske erişim gerektiren I/O yüklerini gösterir [1]. Kaynaklar bu bekleme olaylarını Oracle Database 18 ve 19c referans kılavuzları kapsamında açıklamaktadır [1, 2].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Aktif Oturum Geçmişi (ASH) örnekleme mekanizması AWR raporlarından nasıl ayrılır ve anlık performans sorunlarında nasıl kullanılır?", "a": "ASH, SGA halka tamponunda (v$active_session_history) her saniye aktif oturumları örnekleyerek AWR snapshot saatlik ortalamalarının gizlediği kısa süreli performans sıçramalarını yakalar [1]. Geçmiş ASH verileri disk üzerindeki dba_hist_active_sess_history görünümünden sorgulanır [1]. v$active_session_history görünümü dba_users ve dba_objects ile birleştirilerek dar boğaza neden olan SQL ID, kullanıcı ve nesne doğrudan izole edilir [1]. Kaynaklar ASH örnekleme mekanizması için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Bellekte aktif çalışan bir SQL cümlesinin gerçek yürütme planı ve çalışma zamanı istatistikleri hangi SQL komutu ile çekilir?", "a": "Bellekte aktif çalışan bir SQL cümlesinin gerçek yürütme planı dbms_xplan.display_cursor(sql_id => '&target_sql_id', cursor_child_number => NULL, format => 'ALLSTATS LAST') çağrısıyla çekilir [1, 2]. Yürütme planındaki Tahmini Satır Sayısı (E-Rows) ile Gerçekleşen Satır Sayısı (A-Rows) arasındaki büyük farklar bayat veya eksik tablo istatistiklerine işaret eder [1, 2]. Bu farkların giderilmesi için tablo istatistiklerinin güncellenmesi gerekir [2]. Kaynaklar bu display_cursor kullanımı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [2].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "IFS Applications veritabanlarında satır seviyesinde kilitlenme çekişmeleri (row-level locking) hangi bekleme olayı ile tespit edilir?", "a": "Satır seviyesinde kilitlenme çekişmeleri enq: TX - row lock contention bekleme olayı sorgulanarak tespit edilir [1, 2]. IFS ortamlarında müşteri siparişleri, stok bakiyeleri veya muhasebe kayıtlarının eşzamanlı güncellenmesi sırasında taahhüt edilmemiş (uncommitted) işlemlerden kaynaklanır [2]. Bu bekleme olayı bir oturumun başka bir oturum tarafından kilitlenen satırın serbest bırakılmasını beklediğini gösterir [2]. Kaynaklar bu kilit bekleme olayı için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [2].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Otomatik Veritabanı Teşhis Monitörü (ADDM) veritabanı performans sorunlarını tespit ederken nasıl bir analiz yöntemi izler?", "a": "Otomatik Veritabanı Teşhis Monitörü (ADDM), her AWR snapshot yakalamasının ardından son iki snapshot arasındaki performans verilerini veritabanı süresi (DB Time) odaklı analiz eder [1]. Üst düzey CPU ve bekleme süresi dağılımlarından başlayarak SQL ifadelerine, veritabanı nesnelerine ve donanım kaynaklarına kadar ağaç yapısında yukarıdan aşağıya bir teşhis yürütür [1]. Bu yaklaşım verimli çalışan bileşenleri eleyerek doğrudan yüksek etkili sorunlara odaklanılmasını sağlar [1]. Kaynaklar ADDM analiz yöntemi için belirli bir veritabanı sürümü kısıtlaması belirtmemektedir [1].", "sources": [{"title": "ADDM Report Analysis & Proactive Recommendations", "url": ""}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Otomatik İş Yükü Deposu (AWR) raporlarında yer alan DB Time metriği ile Elapsed Time arasındaki ilişki veritabanı performansı açısından ne anlam ifade eder?", "a": "AWR raporlarında DB Time metriği, aktif kullanıcı oturumlarının CPU ve bekleme olaylarında harcadığı toplam süreyi temsil eder [1, 2]. DB Time değerinin geçen süreyi (Elapsed Time) belirgin şekilde aşması, veritabanında yüksek eşzamanlılık (concurrency) veya ciddi kaynak çekişmesi olduğunu gösterir [1, 2]. Bu durum sistemde aynı anda birden fazla oturumun kaynak beklediğine işaret eder [1]. Kaynaklar bu AWR metrik ilişkisi için spesifik bir veritabanı sürümü belirtmemektedir [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Performans sorunlarının yama uygulaması sonrasındaki değişimini kıyaslamak için hangi AWR rapor türü ve SQL betiği kullanılır?", "a": "Yama güncellemeleri (Release Update veya Release Update Revision) öncesi ve sonrasındaki veritabanı davranışını kıyaslamak için AWR Compare Period raporları kullanılır [1]. Bu karşılaştırma raporları tekil veritabanı örneklerinde awrddrpt.sql betiği ile, Oracle RAC ortamlarında ise awrddrpi.sql betiği çalıştırılarak üretilir [1]. Raporlar yük profili ve kaynak tüketimindeki değişimleri yan yana sunarak performans gerilemelerini (regression) tespit eder [1]. Kaynaklar bu AWR kıyaslama betiklerini yama güncellemeleri bağlamında sunmaktadır [1].", "sources": [{"title": "ADDM Report Analysis & Proactive Recommendations", "url": ""}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Resmî Oracle kılavuzunda C.3 Descriptions of Wait Events bölümünün veritabanı performans teşhisindeki amacı nedir?", "a": "Resmî Oracle kılavuzu Database Reference 18 bünyesindeki C.3 Descriptions of Wait Events bölümü, oturumların hangi operasyonel nedenlerle durakladığını açıklayan veri sözlüğü kataloğudur [1]. Katalogda I/O, tampon bellek, kilitlenme ve küme iletişimine ait bekleme olaylarının çalışma mekanizmaları ve parametreleri tanımlanır [1]. Veritabanı yöneticileri oturumların duraklama nedenlerini anlamak için bu referans kataloğundan yararlanır [1]. Resmî kılavuz bu bekleme olayları kataloğunu Oracle Database Release 18 sürümü için belgelemektedir [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "Shared Pool ve Library Cache bellek alanlarındaki latch ve mutex çekişmeleri hangi bekleme olayları ile ortaya çıkar?", "a": "Bellek çekişmeleri cursor: mutex S, cursor: mutex X, cursor: pin S wait on X, cursor: pin X ve library cache: mutex X bekleme olayları ile ortaya çıkar [1, 2]. Bu çekişmeler yüksek miktarda sabit ayrıştırma (hard parse) ve paylaşılamayan SQL ifadelerinin Shared Pool üzerinde yarattığı baskıdan tetiklenir [2]. Aşırı ayrıştırma yükü bellek yapılarının kilitlenmesine neden olur [2]. Kaynaklar bu mutex ve latch bekleme olaylarını Oracle Database 18 referans kılavuzunda sunmaktadır [1].", "sources": [{"title": "AWR Performance Metrics Interpretation", "url": ""}, {"title": "C.3 Descriptions of Wait Events - Oracle Help Center", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/18/refrn/descriptions-of-wait-events.html"}]}, {"chapter": 8, "title": "Bölüm 8: Performans Yönetimi, Tuning ve Teşhis Araçları", "q": "sga_target, pga_aggregate_target, open_cursors ve processes parametreleri ORA-01000 ve ORA-00020 hatalarını önlemedeki rolleri açısından kaynaklarda nasıl açıklanmaktadır?", "a": "ADDM raporları sga_target, pga_aggregate_target, open_cursors ve processes parametrelerinin ayarlanmasını yapılandırma seviyesinde aksiyon alınabilir çözümler olarak sunmaktadır [1]. Ancak seçilen kaynaklar bu parametrelerin spesifik olarak ORA-01000 veya ORA-00020 hata kodlarını önlemedeki doğrudan ilişkisine dair ayrıntıları bu pasajlarda açıkça belirtmemektedir [1]. Kaynakların kapsamadığı bu hata kodu detayları kaynaklarda yer almadığı için açıkça ifade edilmiştir [1]. Kaynaklar bu ADDM önerileri için özel bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "ADDM Report Analysis & Proactive Recommendations", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 25R1 Kibana arayüzünde toplanan metrikleri incelemek için Response Time Detail View Dashboard nasıl çalışır?", "a": "Response Time Detail View Dashboard, Kibana arayüzüne gerekli dosyalar yüklenip veri görünümü oluşturulduktan sonra projeksiyon ve varlık (projections and entities) metriklerini sunar. Dashboard ekranı metrikleri varsayılan olarak en yüksek yanıt süresinden en düşük yanıt süresine doğru sıralayarak görüntüler. Bu sıralama sayesinde teknik ekipler sistemdeki en yavaş çalışan operasyonları doğrudan izole eder. Kaynaklar bu dashboard aracını IFS Cloud 25R1 sürümü kapsamına tarihlendirmektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 25R1 Remote Deploy mimarisinde EFK stack log izleme altyapısı hangi bileşenlerden oluşur ve verileri ne kadar süre saklar?", "a": "IFS Cloud 25R1 Remote Deploy mimarisinde günlük izleme altyapısı Elasticsearch, Fluentd ve Kibana bileşenlerinden oluşan bir EFK stack ile yürütülür. Elasticsearch günlük verilerini zorunlu 7 günlük saklama süresiyle tutar ve günlük çalışan curator cronjob 7 günden eski kayıtları otomatik olarak siler. Fluentd günlük toplayıcı ve iletici işlevini üstlenirken Kibana veri görselleştirme ve sorgulama imkanı sunar. Kaynaklar bu EFK stack yapısını IFS Cloud 25R1 sürümüne özgü olarak belirtmektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 26R2 Application Monitoring Metrics (AMM) ve Application Monitoring Console (AppMon) mimarisi metrikleri nasıl değerlendirir?", "a": "AMM mimarisi metrikleri tanımlanmış eşik ifadelerine göre değerlendirerek OK, Warning, Critical veya Unknown servis durum kodlarını üretir. Solution Manager altından erişilen Application Monitoring Console (AppMon), metrik durumlarını görselleştirir ve Show Alarms Only filtresi ile problemli alanları izole eder. Foundation1 Monitoring zamanlanmış görevi günlük olarak çalışarak aktif metrik durumlarını günceller. Kaynaklar AMM ve AppMon izleme araçlarını doğrudan IFS Cloud 26R2 sürümüne ait olarak sunmaktadır.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 26R2 Server Alert Log Categories sayfasında tanımlanan varsayılan kategori türleri ve parametreleri nelerdir?", "a": "Server Alert Log Categories sayfasındaki her kategori Enable, Cleanup ve Days to keep saklama parametreleri ile yönetilir. Standart kategoriler arasında Ddl Audit, Debug, Deployment, Deployment detail, Event errors, Server Errors (ORA hataları), Sql Injections ve In-Memory kategorileri yer alır. Bu kategoriler sunucu olaylarını veritabanı tetikleyicileri veya iç denetim kuralları üzerinden kaydeder. Kaynaklar bu Server Alert Log kategorilerini IFS Cloud 26R2 sürümüne ait olarak detaylandırmaktadır.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 26R2 Streams işlevselliği arka plan işleri tamamlandığında son kullanıcılara bildirim iletimini nasıl gerçekleştirir?", "a": "Streams işlevselliği, Transaction_SYS.Deferred_Call tek seferlik işleri ve Batch_SYS.New_Batch_Schedule zamanlanmış görevleri tamamlandığında Transaction_SYS.Process_All_Pending zamanlayıcısı üzerinden bildirim gönderir. Bildirimler stream_msg_on_completion_ ve stream_notes_ parametreleri ile etkinleştirilir ve Transaction_SYS.Modify_Stream_Notification Hooking API'si ile özelleştirilebilir. Bu yapı arka plan rapor ve görev sonuçlarını kullanıcılara duyurur. Kaynaklar Streams bildirim mekanizmasını IFS Cloud 26R2 sürümüne tarihlendirmektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "IFS Cloud 26R2 ortamlarında Oracle Advanced Queues mesajlaşma yapısı hangi pencereler üzerinden yönetilir?", "a": "Solution Manager altındaki Oracle Queues penceresi üzerinden asenkron mesajlaşma kuyruk tabloları başlatılabilir, durdurulabilir ve temizlenebilir. Oracle Queue Subscribers penceresi üzerinden ise aktif aboneler (subscribers) takip edilebilir veya sistemden kaldırılabilir. Bu arayüzler veritabanı mesaj akışının ve arka plan süreçlerinin kontrolünü sağlar. Kaynaklar Oracle Queues arayüz yönetimini IFS Cloud 26R2 sürümüne özgü olarak belgelendirmektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "OEM Incident Rule Set ve Blackout takvimleri yanlış alarmları önlemek için nasıl yapılandırılır?", "a": "Incident Rule Set yapıları hedef kriterleri ve zaman pencerelerine göre otomatik bildirimler gönderme, betik çalıştırma veya dış biletleme sistemlerinde bilet açma adımlarını yönetir [1]. Planlı bakım pencerelerinde idari Blackout takvimleri tanımlanarak rutin bakımlar sırasında alarm bildirimi gönderilmesi geçici olarak bastırılır [1]. Bu bastırma mekanizması IFS staging veya üretim ortamlarında yanlış alarmların önüne geçer [1]. Kaynaklar bu kural kümeleri ve blackout takvimleri için spesifik bir sürüm belirtmemektedir [1].", "sources": [{"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "OEM olay yönetimi mimarisinde Event seviyesinden Incident seviyesine yükseltme (promotion) mantığı nasıl çalışır?", "a": "Oracle Management Agent (OMA) hedef metriklerini sürekli örnekler ve bir metrik uyarı veya kritik eşiği geçtiğinde sistem bir Event üretir [1]. Üretilen Event, tanımlanmış olay kuralları ve ciddiyet seviyeleri doğrultusunda idari müdahale gerektiren bir Incident seviyesine otomatik olarak yükseltilir [1]. Bu yükseltme mekanizması kritik sistem durumlarının takibini otomatikleştirmektedir [1]. Kaynaklar bu event ve incident yaşam döngüsü için belirli bir veritabanı sürümü kısıtlaması koymamaktadır [1].", "sources": [{"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "Oracle Enterprise Manager (OEM) Cloud Control mimarisinde OMS, OMR ve OMA altyapı bileşenlerinin temel görevleri nelerdir?", "a": "Oracle Management Service (OMS), WebLogic üzerinde çalışan ve metrikleri işleyerek Cloud Control konsolunu sunan orta katman yazılımıdır. Oracle Management Repository (OMR), SYSMAN şemasında metrik verilerini ve yapılandırmaları saklayan adanmış veritabanıdır. Oracle Management Agent (OMA) ise hedef sunucularda çalışan ve TCP 3872 portu üzerinden OMS bileşenine metrik toplayıp yükleyen süreçtir. Kaynaklar bu altyapı bileşenleri için OEM 13c/14c mimari kurulumunu temel almakta ve işlevsel bir sürüm farkı belirtmemektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 9, "title": "Bölüm 9: İzleme, Alarm ve Olay Yönetimi Mimarisi", "q": "Oracle Enterprise Manager (OEM) ortamında emctl komut satırı aracı ile hangi altyapı yönetim işlemleri gerçekleştirilir?", "a": "emctl aracı OMS sunucusu üzerinde WebLogic servislerinin, HTTP sunucusunun ve repository bağlantısının durumunu denetlemek için kullanılır. Yönetilen hedef düğümlerde ise OMA agent süreç sağlığı ve OMS ping bağlantısı emctl status agent ile doğrulanır veya emctl upload agent ile telemetri verileri OMS ortamına anında yüklenir. Bu komut satırı aracı altyapı bileşenlerinin operasyonel yönetimi için standarttır. Kaynaklar bu emctl komutları için OEM 13c/14c arasında spesifik bir sürüm kısıtlaması belirtmemektedir.", "sources": [{"title": "OEM 13c/14c Infrastructure Setup", "url": ""}, {"title": "Automated Incident Rule sets & Notifications", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-010-response-time-detail-view-dashboard-2026-11-08-09_29_51.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-25r1-070-remote-deploy-010-installing-fresh-system-030-preparing-server-54-log-monitoring-2026-11-08-09_27_30.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-047-database-alert-log-categories-2026-11-08-10_11_21.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-120-app-mon-console-2026-11-08-10_12_26.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-about-streams-background-jobs-2026-11-08-10_13_04.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-2026-11-08-10_09_39.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-008-metrics-details-2026-11-08-10_22_28.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-010-app-mon-metrics-concepts-2026-11-08-10_31_31.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-020-app-mon-100-app-mon-metrics-030-app-mon-metrics-2026-11-08-10_34_44.pdf", "url": ""}, {"title": "Technical Administration and Operational Governance in IFS Cloud 26R2", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-120-monitoring-080-oracle-queues-2026-11-08-10_35_49.pdf", "url": ""}, {"title": "screencapture-docs-ifs-techdocs-26r2-030-administration-140-system-info-and-util-022-system-performance-2026-11-08-10_40_05.pdf", "url": ""}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "11.11.2026 tarihli kesinti incelemesi sonrasında IFS Applications canlıya alım (deploy) öncesi kontrol listelerine hangi idari denetim kuralı eklenmiştir?", "a": "Kesinti incelemesi bulguları doğrultusunda, canlıya alım öncesinde arka planda tamamlanmamış veya takılmış toplu iş kalıp kalmadığını denetleyen denetim kuralı canlıya alım kontrol listesine eklenmiştir [1]. Bu kural, canlıya alım öncesinde çalışan arka plan işi olmadığını (no active background jobs) veritabanı sorgularıyla doğrulamayı şart koşar [1]. Böylece deploy sırasında nesnelerin geçersiz (INVALID) duruma düşmesi ve AQ kuyruklarında mesaj birikmesi engellenir [1].", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "IFS kesinti inceleme dokümanına göre Oracle Advanced Queues (AQ) mesaj birikmesi tespiti için hangi metrik ve alarm eşiği önerilmektedir?", "a": "IFS altyapısında asenkron işleyiciler takıldığında mesajlar Oracle Advanced Queues (AQ) kuyruklarında birikir [1, 2]. Veriler ifs_aq metriğinde toplanmakta olup bekleyen (ready) mesaj sayısının uzun süre düşmediği durumlar için AQ birikme alarmı tanımlanması önerilmiştir [1]. Bu uyarı sinyali, arka plan işleyicilerinin durakladığını erkenden haber vererek kesintilerin önüne geçer [1].", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}, {"title": "IFS Oracle Eğitim İçeriği Güncellemesi", "url": ""}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "Kesinti sonrası adli incelemelerde Oracle Scheduler işlerini analiz etmek ve alert log hatalarını taramak için hangi salt okunur SQL sorguları çalıştırılır?", "a": "Kesinti zaman aralığında Oracle Scheduler işlerinin durumunu incelemek amacıyla dba_scheduler_job_run_details görünümünden job_name, status, actual_start_date ve run_duration sütunları sorgulanır [1]. Oracle alert log kayıtlarındaki kritik hataları tespit etmek için v$diag_alert_ext görünümünden ORA- veya deadlock içeren mesajlar originating_timestamp ve message_text sütunlarından taranır [1]. Bu sorgular Diagnostics veya Tuning Pack lisansı gerektirmeden kesinti adımlarını ortaya çıkarır [1].", "sources": [{"title": "Kesinti incelemesi hazırlığı — 11.11.2026.docx", "url": ""}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "Oracle 26ai veritabanında RMAN RECOVER TABLE komutunun tablo kurtarma detayları hakkında kaynaklar hangi bilgileri vermektedir?", "a": "Seçilen kaynaklar içerisinde Oracle 26ai veritabanında RMAN RECOVER TABLE komutu ile tablo seviyesinde kurtarma yapılmasına dair herhangi bir detay veya kural bulunmamaktadır [1]. Kaynaklar tablo ve bölüm seviyesinde kurtarma adımlarını Oracle Database 19c ve Oracle Database 12c sürümleri kapsamında belgelendirmektedir [1]. Kaynakların kapsamadığı Oracle 26ai tablo kurtarma ayrıntıları kaynaklarda yer almadığı için açıkça ifade edilmiştir [1].", "sources": [{"title": "Recovering Tables and Table Partitions", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-recovering-tables-partitions.html"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "Oracle Database 19c sürümünde Data Recovery Advisor (DRA) özelliğinin kullanımdan kaldırılması (deprecation) hangi RMAN komutlarını etkilemiştir?", "a": "Oracle Database 19c sürümünde Data Recovery Advisor (DRA) özelliği kullanımdan kaldırılmıştır (deprecated) [1]. Bu kaldırma işlemi doğrultusunda LIST FAILURE, ADVISE FAILURE, REPAIR FAILURE ve CHANGE FAILURE RMAN komutları amorti edilmiş olup veritabanı yöneticilerinin kullanımına kapatılmıştır [1]. Resmî dokümantasyon DRA özelliği için doğrudan sunulmuş yeni bir alternatif komut veya ikame mekanizma bulunmadığını açıkça belirtmektedir [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "Oracle Database 19c sürümünde depolama anlık görüntüsü (storage snapshot) üzerinden veritabanı kurtarma yöntemindeki değişiklik ve önerilen yaklaşım nedir?", "a": "Oracle Database 19c sürümünde depolama anlık görüntülerini kullanarak nokta zamanlı kurtarma yapmayı sağlayan RECOVER...SNAPSHOT TIME yöntemi kullanımdan kaldırılmıştır (deprecated) [1]. Oracle, veritabanı açıkken anlık görüntü alınmadan önce ve sonra ALTER DATABASE BEGIN/END BACKUP komutlarının çalıştırılmasını şart koşmaktadır [1]. Depolama görüntüsü alındıktan sonra kurtarma işlemi END BACKUP tamamlanma zamanından sonraki bir SCN veya zamana RECOVER...UNTIL TIME komutuyla yürütülür [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "RMAN DUPLICATE komutu ile Pluggable Database (PDB) kopyalama desteği hangi sürümde getirilmiştir ve temel çalışma prensibi nedir?", "a": "Oracle Database 18c sürümünde tanıtılan ve Oracle Database 19c sürümünde desteklenen DUPLICATE PLUGGABLE DATABASE komutu, bir PDB'yi mevcut bir CDB içerisine kopyalamaya imkan tanır [1]. Bu işlemin gerçekleşebilmesi için kaynak ve hedef CDB ortamlarında COMPATIBLE başlangıç parametresinin 18.0.0 veya üzeri olarak ayarlanması zorunludur [1]. Komut, doğrudan açık veritabanından active duplication veya mevcut yedek kümelerinden backup-based duplication modlarında yürütülebilir [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "RMAN FLASHBACK DATABASE komutunun genel çalışma altyapısı ve PDB seviyesindeki teknik kısıtlamaları nelerdir?", "a": "FLASHBACK DATABASE komutu, veri dosyalarını yedekten geri yüklemeye gerek kalmadan Hızlı Kurtarma Alanı (FRA) içinde saklanan flashback loglarını kullanarak veritabanını geçmiş bir SCN veya zaman noktasına geri sarar. Pluggable Database (PDB) seviyesinde flashback işlemleri Oracle Database 12c Release 2 (12.2) ve üzeri sürümlerde COMPATIBLE >= 12.2.0.0 olduğunda desteklenir [1]. Ancak resmî dokümantasyon proxy PDB yapılarında flashback operasyonlarının desteklenmediğini açıkça belirtmektedir [1].", "sources": [{"title": "Oracle Database Backup and Recovery Reference - Oracle Help", "url": "https://docs.oracle.com/en/database/oracle//oracle-database/19/rcmrf/oracle-ai-database-backup-and-recovery-reference.pdf"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "RMAN RECOVER TABLE komutu ile tablo seviyesinde nokta zamanlı kurtarma (PITR) yapılırken arka planda hangi otomasyon adımları yürütülür?", "a": "RMAN, hedef sunucuda belirtilen AUXILIARY DESTINATION konumunda otomatik olarak geçici bir yardımcı veritabanı (auxiliary database) örneği oluşturarak gerekli yedekleri buraya geri yükler [1]. Nesneler belirlenen hedef zaman noktasına kadar kurtarıldıktan sonra RMAN, bu verileri içeren bir Data Pump döküm dosyası (export dump file) üretir [1]. Üretilen döküm dosyası hedef veritabanına otomatik aktarılır (import edilir) veya NOTABLEIMPORT tümcesi kullanılarak aktarım adımı atlanır [1].", "sources": [{"title": "Recovering Tables and Table Partitions", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-recovering-tables-partitions.html"}]}, {"chapter": 10, "title": "Bölüm 10: Yedekleme, Kurtarma ve Operasyonel Uygulama", "q": "RMAN RECOVER TABLE komutunda kurtarılan tabloları farklı bir şemaya ve farklı bir tablespace alanına aktarmak için hangi yan tümceler kullanılır?", "a": "Kurtarılan tabloları hedef veritabanında farklı bir tablespace alanına aktarmak için REMAP TABLESPACE yan tümcesi kullanılır [1]. Oracle Database 12c Release 2 (12.2) sürümünden itibaren REMAP TABLE yan tümcesi ile nesneler hem farklı bir tablo adına yeniden adlandırılabilir hem de doğrudan orijinal şemadan farklı yeni bir hedef şemaya aktarılabilir [1]. Bu yeniden eşleme adımlarında tanımlı kısıtlamalar (constraints) ve indeksler aktarılmaz [1].", "sources": [{"title": "Recovering Tables and Table Partitions", "url": "https://docs.oracle.com/en/database/oracle/oracle-database/19/bradv/rman-recovering-tables-partitions.html"}]}]}};
